test("outbox 夹具 helper 自己守约束：合法产出过审计；坏样本必须显式声明且声明要与读模型逐字相符", () => {
  // ① outboxRecord 的默认产出与合法扩展，落盘后审计干净 —— 约束在 helper 里，不靠调用处记得。
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "fixture-sem-"));
  fs.writeFileSync(path.join(dir, "0001.json"), JSON.stringify(outboxRecord()));
  fs.writeFileSync(path.join(dir, "0002.json"), JSON.stringify(outboxRecord({ kind: "reply", text: "x",
    target_channel_generation_id: "gen-1", publish_eligible_at: "2026-08-26T00:00:00.000Z", publish_attempts: 2 })));
  assert.deepEqual(auditOutbox(dir), { ok: true, pending: 2, unclassified: [], unexplainable: [], files: ["0001.json", "0002.json"] });
  // ② outboxRecord 造不出坏样本：每一类坏形状都当场抛，并指路 invalidOutboxRecord。
  for (const [why, extra] of [
    ["kind 不在受控取值里", { kind: "progress" }],
    ["id 纯空白", { id: "   " }],
    ["正文为空", { text: "  " }],
    ["created_at 不规范", { created_at: "昨天" }],
    ["目标代际纯空白", { target_channel_generation_id: "   " }],
    ["授权字段畸形", { publish_eligible_at: "not-a-canonical-time" }],
    ["重试保护写坏", { publish_attempts: "five" }],
    ["published_at 放 false", { published_at: false }],
    ["既发布又停发", { published_at: "2026-08-24T00:00:00.000Z", publish_suppressed_at: "2026-08-24T00:00:00.000Z" }],
  ]) assert.throws(() => outboxRecord(extra), /invalidOutboxRecord/u, why + "：outboxRecord 不许造出坏样本");
  // ③ invalidOutboxRecord：必须声明；声明要与读模型逐字相符（why 原文、gaps 有序逐字）；没声明的那一项必须干净。
  assert.throws(() => invalidOutboxRecord({ target_channel_generation_id: "   " }), /必须声明预期阻断原因/u, "不声明不行");
  // expect 是封闭联合："声明了却什么都没说"的形状一律拒绝（评审探针：gaps:[] / unclassified:null 曾放行合法记录）。
  for (const [why, expect, pattern] of [
    ["gaps 空数组", { gaps: [] }, /gaps 必须是非空的字符串数组/u],
    ["gaps 不是数组", { gaps: "kind" }, /gaps 必须是非空的字符串数组/u],
    ["gaps 含空串", { gaps: ["kind", ""] }, /gaps 必须是非空的字符串数组/u],
    ["unclassified 为 null", { unclassified: null }, /unclassified 必须是非空字符串/u],
    ["unclassified 为空串", { unclassified: "" }, /unclassified 必须是非空字符串/u],
    ["不认识的键", { reason: "x" }, /不认识的键 reason/u],
    ["expect 是数组", ["kind"], /必须声明预期阻断原因/u],
    ["expect 为空对象", {}, /必须声明预期阻断原因/u],
  ]) assert.throws(() => invalidOutboxRecord({ expect }), pattern, why);
  assert.throws(() => invalidOutboxRecord({ omit: "published_at", expect: { unclassified: "缺 published_at，无法归类" } }), /omit 必须是字符串数组/u);
  assert.throws(() => invalidOutboxRecord({ target_channel_generation_id: "   ", expect: { gaps: ["kind"] } }),
    /声明的解释缺口是 \["kind"\]，实际 \["target_channel_generation_id"\]/u, "gaps 声明错了要抛");
  assert.throws(() => invalidOutboxRecord({ published_at: false, expect: { unclassified: "published_at 不对" } }),
    /声明的三态阻断原因/u, "why 声明错了要抛（不是子串匹配，是逐字）");
  assert.throws(() => invalidOutboxRecord({ published_at: false, target_channel_generation_id: "   ",
    expect: { gaps: ["target_channel_generation_id"] } }), /声明的三态阻断原因是 null/u, "只声明 gaps 而记录还三态判不出来 → 抛");
  assert.throws(() => invalidOutboxRecord({ published_at: false, target_channel_generation_id: "   ",
    expect: { unclassified: "published_at 既不是 null 也不是规范时间" } }), /声明的解释缺口是 \[\]/u, "只声明 unclassified 而 gaps 非空 → 抛");
  assert.throws(() => invalidOutboxRecord({ text: "其实合法", expect: { gaps: ["text"] } }), /实际 \[\]/u, "把合法样本声明成坏的也要抛");
  // 声明正确：产出落盘后审计给出的就是声明的那个原因。
  const dir2 = fs.mkdtempSync(path.join(os.tmpdir(), "fixture-sem2-"));
  fs.writeFileSync(path.join(dir2, "gap.json"), JSON.stringify(invalidOutboxRecord({
    target_channel_generation_id: "   ", expect: { gaps: ["target_channel_generation_id"] } })));
  fs.writeFileSync(path.join(dir2, "cls.json"), JSON.stringify(invalidOutboxRecord({
    omit: ["published_at"], expect: { unclassified: "缺 published_at，无法归类" } })));
  fs.writeFileSync(path.join(dir2, "both.json"), JSON.stringify(invalidOutboxRecord({
    published_at: false, target_channel_generation_id: "   ",
    expect: { unclassified: "published_at 既不是 null 也不是规范时间", gaps: ["target_channel_generation_id"] } })));
  fs.writeFileSync(path.join(dir2, "raw.json"), rawOutboxFixture({ raw: "{ 坏了", expect: { unclassified: "读不出来" } }));
  fs.writeFileSync(path.join(dir2, "arr.json"), rawOutboxFixture({ raw: "[1]", expect: { unclassified: "不是记录对象" } }));
  const a = auditOutbox(dir2);
  assert.deepEqual(a.unclassified.map((u) => [u.file, u.why]).sort(), [
    ["arr.json", "不是记录对象"], ["both.json", "published_at 既不是 null 也不是规范时间"],
    ["cls.json", "缺 published_at，无法归类"], ["raw.json", "读不出来"]]);
  assert.deepEqual(a.unexplainable.map((u) => u.file).sort(), ["both.json", "gap.json"]);
  // ④ rawOutboxFixture 同样要声明且相符。
  assert.throws(() => rawOutboxFixture({ raw: "{ 坏了" }), /需要 raw 字符串与 expect/u);
  assert.throws(() => rawOutboxFixture({ raw: "{ 坏了", expect: { unclassified: "不是记录对象" } }), /实际 "读不出来"/u);
  assert.throws(() => rawOutboxFixture({ raw: JSON.stringify(outboxRecord()), expect: { unclassified: "读不出来" } }), /实际 null/u, "合法记录不能装成坏的");
});

test("第五区 run 通道：只转述 inspectRunChannel 的结论 —— 未查 / 说不清 / 暂停未分类 各自明写，不折叠成 0", () => {
  const now = Date.parse("2026-08-27T12:00:00.000Z");
  const rowsOf = (rc) => runChannelRows(rc, now);
  const text = (rc) => {
    const full = renderLayeredStatus(composeLayeredStatus({
      st: layeredSt(), runChannel: rc, now,
      endpoint: { runtime: "Claude Code", agentName: "M5Claude", install: "ok", installReason: null, version: "abc123",
        selfCheck: ENDPOINT_SELF_CHECK, lastInboundAt: null },
      subscription: { ok: true, items: [], pendingCount: 0 },
    }));
    return full.slice(full.indexOf("待处理事件"));
  };
  // 没传 = 没查：不许显示成 0 条。
  assert.deepEqual(rowsOf(undefined), [["run 通道", "未查（本次没读 runs 账本）"]]);
  assert.doesNotMatch(text(undefined), /run 待发|run 卡住/u, "没查就不许出计数行");
  // runs 账本打不开：只说"说不清"，不给任何计数。
  const unreadable = { phase: "classified", inventoryOk: false, waiting: { count: 0, oldestMs: null },
    runs: { pending: 0, published: [], skipped: [], stuck: [], deliveredUnrecorded: [], problems: [{ key: null, reason: "runs_unreadable", why: "EACCES" }] } };
  assert.deepEqual(rowsOf(unreadable), [["run 通道", "说不清（runs_unreadable：EACCES）"]]);
  // 项目解析不出：说不清 + 账本里的待处理条数照报。
  const unresolved = { phase: "unresolved", reason: "not_bound", inventoryOk: true, waiting: { count: 2, oldestMs: null },
    runs: { pending: 2, published: [], skipped: [], stuck: [], deliveredUnrecorded: [], problems: [] } };
  assert.deepEqual(rowsOf(unresolved), [["run 通道", "说不清（not_bound）；账本里有 2 条待处理"], ["runs 账本", "无异常"]]);
  // 解析不出的项目，盘点里 key 为 null 的问题（不认识的条目 / claims 目录读不出）照样一条不漏（评审探针）。
  const unresolvedWithProblem = { ...unresolved, waiting: { count: 0, oldestMs: null },
    runs: { ...unresolved.runs, pending: 0, problems: [{ key: null, reason: "unrecognized_entry", why: "runs/unknown-entry" }] } };
  assert.deepEqual(rowsOf(unresolvedWithProblem), [["run 通道", "说不清（not_bound）；账本里有 0 条待处理"],
    ["runs 账本", "说不清 1 处"], ["  --------", "unrecognized_entry：runs/unknown-entry"]]);
  // 绑定暂停：排空不分类 stuck —— 明写"暂停中未分类"，不许显示"卡住 0 条"。
  const paused = { phase: "paused", reason: "mapping_not_active", inventoryOk: true, waiting: { count: 1, oldestMs: null },
    runs: { pending: 1, published: [], skipped: [], stuck: [], deliveredUnrecorded: [], problems: [] } };
  const pausedRows = rowsOf(paused);
  assert.equal(pausedRows[0][1], "暂停中未分类：1 条待处理（恢复绑定后由排空分类处理，符合条件的再发出）");
  assert.equal(pausedRows.some((r) => r[0] === "run 卡住"), false, "**暂停时不许伪造\"卡住 0 条\"**");
  // 已分类：待发条数 + 最老一条年龄；卡住逐条带 reason；问题逐条；key 只留 8 位；why 里的 key / 消息 id 脱敏。
  const K = "0123456789abcdef".repeat(4);
  const classified = { phase: "classified", reason: null, inventoryOk: true,
    waiting: { count: 1, oldestMs: now - 90 * 60000 },
    runs: { pending: 3, published: [{ key: K, target: "om_fixture" }], skipped: [],
      stuck: [{ key: "f".repeat(64), reason: "route_mismatch", why: "最终投递路由与终局记录绑定的对不上" },
        { key: "e".repeat(64), reason: "reservation_unresolved", why: "上次尝试没闭合（delivered_unrecorded：om_secret123）" }],
      deliveredUnrecorded: [{ key: "d".repeat(64), messageId: "om_delivered", error: "EISDIR" }],
      problems: [{ key: "c".repeat(64), reason: "terminal_unreadable", why: "c".repeat(64) + ".handed_off.json：不是 JSON" }] } };
  const rows = rowsOf(classified);
  assert.deepEqual(rows[0], ["run 待发", "1 条（最老 2 小时前）"]);
  assert.deepEqual(rows[1], ["run 卡住", "2 条（需要人看）"]);
  assert.deepEqual(rows[2], ["  ffffffff", "route_mismatch：最终投递路由与终局记录绑定的对不上"]);
  assert.deepEqual(rows[3], ["  eeeeeeee", "reservation_unresolved：上次尝试没闭合（delivered_unrecorded：om_…）"]);
  assert.deepEqual(rows[4], ["run 送达未落标", "1 条（下一轮可能重发，先去话题核对）"]);
  assert.deepEqual(rows[6], ["runs 账本", "说不清 1 处"]);
  assert.deepEqual(rows[7], ["  cccccccc", "terminal_unreadable：cccccccc….handed_off.json：不是 JSON"]);
  // why 在展示边界截断（真机实测：watcher 失败账把整条 lark 命令连卡片正文带出来，一行几百字）。
  const longWhy = "Command failed: lark-cli --text " + "正文".repeat(200);
  const clipped = rowsOf({ ...classified, runs: { ...classified.runs, stuck: [{ key: "a".repeat(64), reason: "watcher_publish_failed", why: longWhy }] } })[2];
  assert.equal(clipped[1].endsWith("…（已截断）"), true, clipped[1]);
  assert.ok(clipped[1].length < 160, "**截断后一行要能在手机上读完**：" + clipped[1].length);
  assert.equal(clipped[1].startsWith("watcher_publish_failed：Command failed: lark-cli --text 正文"), true);
  // 按 code point 截：边界落在 emoji 中间不许留下孤立代理项。
  const emoji = String.fromCodePoint(0x1F600);
  const emojiWhy = "a" + emoji.repeat(200);
  const clippedEmoji = rowsOf({ ...classified, runs: { ...classified.runs, stuck: [{ key: "a".repeat(64), reason: "x", why: emojiWhy }] } })[2][1];
  const body = clippedEmoji.slice(0, clippedEmoji.indexOf("…（已截断）"));
  const last = body.charCodeAt(body.length - 1);
  assert.equal(last >= 0xD800 && last <= 0xDBFF, false, "**截断不许留下孤立的高代理项**");
  assert.equal(Array.from(body).length, "x：".length + 120, "按 code point 数满 120");
  const rendered = JSON.stringify(rows);
  assert.equal(rendered.includes("f".repeat(64)), false, "**完整 key 不许出现**");
  assert.equal(rendered.includes("om_secret123"), false, "**消息 id 是 locator，不许出现**");
  assert.equal(rendered.includes("om_delivered"), false);
  // 净化规则只有一份（display-safe.mjs）：逐类字面期望 —— 每种 locator、64 位摘要、UUID、控制字符、行分隔符、双向控制符。
  const ESC = String.fromCharCode(27);
  assert.equal(redactRunText("x " + K + " y om_abcdef"), "x 01234567… y om_…");
  assert.equal(redactLocators("cli_app123456 oc_chat123456 ou_user123456 on_union123456 session_123456 thread_123456 omt_topic123456 om_x12345"),
    "cli_… oc_… ou_… on_… session_… thread_… omt_… om_…");
  assert.equal(redactLocators("01911111-2222-7333-8444-555555555555 " + "A".repeat(64)), "01911111… AAAAAAAA…");
  assert.equal(redactLocators("om_ab oc_12345"), "om_ab oc_12345", "主体不足 6 位的不是 locator 形状，不动");
  assert.equal(redactLocators("topic_generation_state_invalid reason_on_disk"), "topic_generation_state_invalid reason_on_disk", "词中间的 on_ 不是 locator");
  assert.equal(redactLocators("prefix_oc_abcdef_suffix group_oc_123456"), "prefix_oc_… group_oc_…", "下划线是分隔符：其后的 locator 照样脱敏");
  assert.equal(sanitizeForDisplay("a" + String.fromCharCode(10) + "b" + ESC + "[2Jc" + String.fromCharCode(0x2028) + "d" + String.fromCharCode(0x61c) + "e" + String.fromCharCode(0x9f) + "f"),
    "a\uFFFDb\uFFFD[2Jc\uFFFDd\uFFFDe\uFFFDf");
  assert.equal(displaySafe("runs/evil" + ESC + "[2J-" + "b".repeat(64) + ".jsonl"), "runs/evil\uFFFD[2J-bbbbbbbb….jsonl", "未识别文件名：控制符压平 + 摘要脱敏");
  // 边界是字符域不是 \b：下划线 / 字母 紧邻的摘要与 UUID 也要脱敏（评审探针 prefix_<摘要>.jsonl）。
  const U = "01911111-2222-7333-8444-555555555555";
  assert.equal(redactLocators("prefix_" + K + ".jsonl"), "prefix_01234567….jsonl");
  assert.equal(redactLocators(K + "_suffix x_" + U + "_y"), "01234567…_suffix x_01911111…_y");
  assert.equal(redactLocators("z" + K), "z01234567…", "字母紧邻也脱敏");
  assert.equal(redactLocators("f" + "a".repeat(63) + "."), "faaaaaaa….", "恰好 64 位 hex 就是摘要形状");
  assert.equal(redactLocators("a".repeat(65)), "a".repeat(65), "65 位 hex 不是 64 位摘要，不动");
  // 渲染进第五区（真实渲染函数）。
  assert.match(text(classified), /待处理事件[\s\S]*run 待发[\s\S]*run 卡住[\s\S]*ffffffff/u);
});

test("真实 feishu-status：第五区报 run 通道的待发 / 卡住 / 账本问题，判据与排空同一份，且零副作用（真实进程）", () => {
  const h = watcherMatrixRunner.fixture();
  const rt = path.join(h.dir, ".runtime-data", "inbound");
  const runs = path.join(rt, "runs");
  const claims = path.join(rt, "delivery-claims");
  const mk = (label, { tamper = null } = {}) => {
    const key = claimKeyFor(label);
    fs.writeFileSync(path.join(runs, key + ".jsonl"), JSON.stringify({ type: "result", is_error: false, result: "结果 " + label }) + "\n");
    writeClaimFixture({ claimsDir: claims, key, root: h.dir });
    recordClaimState({ claimsDir: claims, key, state: "handed_off",
      detail: terminalDetail(runs, key, { publish_deferred: DEFERRED }, { root: h.dir }) });
    if (tamper) tamper(key);
    return key;
  };
  const waiting = mk("st-wait");
  const past = new Date(Date.now() - 3 * 3600_000);
  fs.utimesSync(path.join(runs, waiting + ".jsonl"), past, past);
  const rerouted = mk("st-rerouted", { tamper: (key) => {
    const p = path.join(claims, key + ".handed_off.json");
    const doc = JSON.parse(fs.readFileSync(p, "utf-8")); doc.route_sha256 = "0".repeat(64); fs.writeFileSync(p, JSON.stringify(doc));
  } });
  const badterm = mk("st-badterm", { tamper: (key) => fs.writeFileSync(path.join(claims, key + ".handed_off.json"), "{ 坏了") });
  const snapshot = (dir) => fs.readdirSync(dir).sort().map((f) => {
    const p = path.join(dir, f);
    return f + ":" + (fs.statSync(p).isDirectory() ? "dir:" + fs.readdirSync(p).sort().join(",") : fs.readFileSync(p).toString("base64"));
  }).join("\n");
  const before = snapshot(runs) + "\n--\n" + snapshot(claims);
  const env = { ...process.env, HOME: h.dir, FEISHU_BRIDGE_REGISTRY: path.join(h.dir, "registry.json") };
  delete env.CLAUDE_CODE_SESSION_ID;
  const run = () => spawnSync(process.execPath, [path.resolve("scripts", "feishu-status.mjs"), "--project", h.dir], { encoding: "utf-8", env, timeout: 60_000 });
  const r = run();
  assert.equal(r.status, 0, r.stderr);
  const fifth = r.stdout.slice(r.stdout.indexOf("待处理事件"));
  assert.match(fifth, /run 待发[　 ]+1 条（最老 3 小时前）/u, fifth);
  // 坏终局记录既是"卡住"（排空拿它当授权凭据读不出）也是"账本问题"（盘点点名）—— 两处都照排空的结论转述。
  assert.match(fifth, /run 卡住[　 ]+2 条（需要人看）/u, fifth);
  assert.match(fifth, new RegExp(rerouted.slice(0, 8) + "[　 ]+route_mismatch", "u"), "**卡住的要带 reason**：" + fifth);
  assert.match(fifth, new RegExp(badterm.slice(0, 8) + "[　 ]+terminal_unreadable", "u"), "**账本问题逐条**：" + fifth);
  assert.match(fifth, /runs 账本[　 ]+说不清 1 处/u, fifth);
  assert.equal(r.stdout.includes(rerouted), false, "**完整 key 不许出现在状态页**");
  assert.equal(r.stdout.includes("om_fixture"), false, "**根消息 id 是 locator**");
  // 零副作用：目录字节一致、没有 claim、没有 lark 调用、没有回执。
  assert.equal(snapshot(runs) + "\n--\n" + snapshot(claims), before, "**status 一个字节都不许改**");
  assert.equal(fs.existsSync(path.join(h.dir, "lark-calls.jsonl")), false, "**零发送**");
  // **判据同一份**：排空 dry-run 说的就是状态页说的。
  const drain = drainProject({ root: h.dir, claudeSessionId: null, dryRun: true, publish: () => { throw new Error("dry-run 不许发"); }, diagnose: () => null });
  assert.deepEqual(drain.runs.stuck.map((x) => [x.key, x.reason]).sort(), [[badterm, "terminal_unreadable"], [rerouted, "route_mismatch"]].sort());
  assert.deepEqual(drain.runs.published.map((x) => x.key), [waiting]);
  const rc = inspectRunChannel({ root: h.dir, claudeSessionId: null });
  assert.equal(rc.phase, "classified");
  assert.deepEqual(rc.runs.stuck.map((x) => [x.key, x.reason]), drain.runs.stuck.map((x) => [x.key, x.reason]));
  assert.equal(rc.waiting.count, 1);
  // 绑定暂停：状态页不许伪造"卡住 0 条"，要说暂停中未分类。
  const mapPath = path.join(rt, "active-mapping.json");
  const mapping = JSON.parse(fs.readFileSync(mapPath, "utf-8"));
  fs.writeFileSync(mapPath, JSON.stringify({ ...mapping, status: "suspended" }));
  const paused = run();
  assert.match(paused.stdout, /暂停中未分类：3 条待处理/u, paused.stdout);
  assert.doesNotMatch(paused.stdout, /run 卡住/u);
  fs.writeFileSync(mapPath, JSON.stringify(mapping));
  // runs 目录打不开：说不清，不折叠成 0。
  fs.chmodSync(runs, 0o000);
  let blind;
  try { blind = run(); } finally { fs.chmodSync(runs, 0o700); }
  assert.match(blind.stdout, /run 通道[　 ]+说不清（runs_unreadable/u, blind.stdout);
  assert.doesNotMatch(blind.stdout, /run 待发/u);
  // 未绑定的项目：解析不出也要把 runs 账本里的问题报出来（评审探针：曾同时显示"0 条待处理"和"账本无异常"）。
  const bare = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-status-unbound-"));
  const bareRuns = path.join(bare, ".runtime-data", "inbound", "runs");
  fs.mkdirSync(bareRuns, { recursive: true });
  fs.writeFileSync(path.join(bareRuns, "unknown-entry"), "x");
  const unbound = spawnSync(process.execPath, [path.resolve("scripts", "feishu-status.mjs"), "--project", bare],
    { encoding: "utf-8", env: { ...env, HOME: bare, FEISHU_BRIDGE_REGISTRY: path.join(bare, "registry.json") }, timeout: 60_000 });
  assert.equal(unbound.status, 0, unbound.stderr);
  assert.match(unbound.stdout, /run 通道[　 ]+说不清（not_bound）；账本里有 0 条待处理/u, unbound.stdout);
  assert.match(unbound.stdout, /runs 账本[　 ]+说不清 1 处[\s\S]*unrecognized_entry：runs\/unknown-entry/u, unbound.stdout);
  // 未识别文件名里夹着完整摘要（prefix_<64 位>.jsonl）：经 inventoryRuns → inspectRunChannel → runChannelRows 真实链路，不许泄露。
  const leakName = "prefix_" + "c".repeat(64) + ".jsonl";
  fs.writeFileSync(path.join(bareRuns, leakName), "x");
  const rc2 = inspectRunChannel({ root: bare, claudeSessionId: null });
  const rows2 = runChannelRows(rc2);
  assert.equal(JSON.stringify(rows2).includes("c".repeat(64)), false, "**完整摘要不许进第五区**：" + JSON.stringify(rows2));
  assert.ok(rows2.some((r) => r[1] === "unrecognized_entry：runs/prefix_cccccccc….jsonl"), JSON.stringify(rows2));
  const leaked = spawnSync(process.execPath, [path.resolve("scripts", "feishu-status.mjs"), "--project", bare],
    { encoding: "utf-8", env: { ...env, HOME: bare, FEISHU_BRIDGE_REGISTRY: path.join(bare, "registry.json") }, timeout: 60_000 });
  assert.equal(leaked.stdout.includes("c".repeat(64)), false, leaked.stdout);
  assert.match(leaked.stdout, /prefix_cccccccc….jsonl/u);
});

/**
 * 机器级体检的夹具：一台"机器"= 隔离 HOME + 三张表 + 若干项目目录。provider 脚本只打印，不写盘。
 * 返回 run()（真实入口子进程）与 snapshot()（整棵 HOME 的字节快照，钉只读）。
 */
function doctorMachine({ installRuntime = false } = {}) {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-doctor-"));
  const dir = (...p) => { const d = path.join(home, ...p); fs.mkdirSync(d, { recursive: true }); return d; };
  if (installRuntime) {
    const plan = planRuntimeSync({ sourceRoot: path.resolve("."), home, chain: "claude" });
    assert.equal(plan.ok, true, plan.reason ?? "");
    const applied = applyRuntimeSync(plan, { home, chain: "claude" });
    assert.equal(applied.ok, true, applied.reason ?? "");
  }
  const okProvider = path.join(home, "provider-ok.mjs");
  fs.writeFileSync(okProvider, 'process.stdout.write(JSON.stringify({ schema_version: "feishu-bridge-status/v1", provider_id: process.argv[2] ?? "x", connections: [] }));\n');
  // 会写盘的 provider：证明"默认不执行状态入口脚本"是行为，不是措辞。
  const marker = path.join(home, "PROVIDER_RAN");
  const writingProvider = path.join(home, "provider-writes.mjs");
  fs.writeFileSync(writingProvider, 'import fs from "node:fs"; fs.writeFileSync(' + JSON.stringify(marker) + ', "ran");\n' +
    'process.stdout.write(JSON.stringify({ schema_version: "feishu-bridge-status/v1", provider_id: process.argv[2] ?? "x", connections: [] }));\n');
  const project = (name, { expiresAt, pendingClaimExpiresAt = null, outboxPending = 0, invalidTopicState = false } = {}) => {
    const root = dir("projects", name);
    const inbound = dir("projects", name, ".runtime-data", "inbound");
    fs.writeFileSync(path.join(inbound, "chain-config.json"), JSON.stringify({ project_dir: root, logical_task_key: name, project_display_name: name, task_display_name: name }));
    // 待认领代际用真实 API 造：手写的状态会被解析层判 invalid，那测的就不是"待认领已过期"了。
    let state = null;
    if (pendingClaimExpiresAt) {
      const legacy = topicGenerationStateForLegacy({ root_message_id: "om_root_" + name, status: "active", channel_generation_id: "gen-1" },
        { runtime: "claude", bindingId: name + "@project-files" });
      assert.equal(legacy.ok, true, JSON.stringify(legacy));
      const prepared = prepareTopicRotation(legacy.state, { operationId: "op-" + name });
      assert.equal(prepared.ok, true, JSON.stringify(prepared));
      const registered = registerPendingTopicGeneration(prepared.state, { operationId: "op-" + name, rootMessageId: "om_pending_" + name, pendingToken: "tok", claimExpiresAt: pendingClaimExpiresAt });
      assert.equal(registered.ok, true, JSON.stringify(registered));
      state = registered.state;
    }
    fs.writeFileSync(path.join(inbound, "active-mapping.json"), JSON.stringify({
      status: "active", root_message_id: "om_root_" + name, claude_session_id: null, channel_generation_id: "gen-1", expires_at: expiresAt,
      ...(state ? { topic_generation_state: state } : {}),
      ...(invalidTopicState ? { topic_generation_state: { generations: "不是数组" } } : {}) }));
    if (outboxPending > 0) {
      const ob = dir("projects", name, ".runtime-data", "outbound", "outbox");
      for (let i = 1; i <= outboxPending; i += 1) fs.writeFileSync(path.join(ob, "000" + i + ".json"), JSON.stringify(outboxRecord({ text: name + " 积压 " + i })));
    }
    return root;
  };
  const files = { registry: path.join(home, "registry.json"), routes: path.join(home, "routes.json"), providers: path.join(home, "providers.json") };
  const writeTables = ({ projects = [], routes = [], sessions = {}, providers = [] }) => {
    fs.writeFileSync(files.registry, JSON.stringify({ schema_version: "1.0", projects }));
    fs.writeFileSync(files.routes, JSON.stringify({ routes, sessions }));
    fs.writeFileSync(files.providers, JSON.stringify({ providers }));
  };
  const provider = (id, { script = okProvider, projectRoot = home, enabled = true } = {}) => ({
    id, protocol: "feishu-bridge-status/v1", executable: process.execPath, script, args: [id], allowed_kinds: ["transport"], project_root: projectRoot, enabled,
  });
  const route = (id, handler = okProvider) => ({ id, handler });
  const snapshot = () => {
    const out = [];
    const walk = (d) => { for (const n of fs.readdirSync(d).sort()) { const p = path.join(d, n); const st = fs.lstatSync(p); if (st.isDirectory()) walk(p); else out.push(path.relative(home, p) + ":" + (st.isSymbolicLink() ? "->" + fs.readlinkSync(p) : fs.readFileSync(p).toString("base64"))); } };
    walk(home); return out.join("\n");
  };
  const run = (extraEnv = {}, args = ["--json"]) => spawnSync(process.execPath, [path.resolve("scripts", "doctor.mjs"), ...args], {
    encoding: "utf-8", timeout: 120_000,
    env: { ...process.env, HOME: home, FEISHU_BRIDGE_REGISTRY: files.registry, FEISHU_BRIDGE_ROUTES: files.routes,
      FEISHU_BRIDGE_STATUS_PROVIDERS: files.providers, CODEX_HOME: path.join(home, ".codex"), FEISHU_CODEX_BRIDGE_HOME: path.join(home, ".codex", "feishu-bridge"), ...extraEnv } });
  return { home, okProvider, writingProvider, marker, project, writeTables, provider, route, snapshot, run, files };
}
const doctorReport = (r) => { assert.ok(r.stdout, r.stderr); return JSON.parse(r.stdout); };
const checkOf = (report, id) => { const c = report.checks.find((x) => x.id === id); assert.ok(c, "缺检查 " + id + "：" + JSON.stringify(report.checks.map((x) => x.id))); return c; };

test("doctor：坏机器 —— 六项各自 fail 且点名，退出码 1，只读，不泄露 locator（真实进程）", () => {
  const m = doctorMachine();
  const now = Date.now();
  const soon = new Date(now + 3 * 86400000).toISOString();
  const pastClaim = new Date(now - 86400000).toISOString();
  const good = m.project("good", { expiresAt: "2099-01-01T00:00:00.000Z" });
  const bad = m.project("bad", { expiresAt: soon, pendingClaimExpiresAt: pastClaim, outboxPending: 2 });
  const gone = m.project("gone", { expiresAt: new Date(now - 86400000).toISOString() });
  const weird = m.project("weird", { expiresAt: "2099-01-01T00:00:00.000Z", invalidTopicState: true });
  m.writeTables({
    projects: [{ id: "good", root: good, root_message_id: "om_root_good", status: "active", expires_at: "2099-01-01T00:00:00.000Z" },
      { id: "bad", root: bad, root_message_id: "om_root_bad", status: "active", expires_at: soon },
      { id: "gone", root: gone, root_message_id: "om_root_gone", status: "active", expires_at: new Date(now - 86400000).toISOString() },
      { id: "weird", root: weird, root_message_id: "om_root_weird", status: "active", expires_at: "2099-01-01T00:00:00.000Z" }],
    routes: [m.route("good"), m.route("lonely"), m.route("brokenroute"), m.route("writer")],
    sessions: { "session_aaaaaaaaaaaa": "good", "session_ghostghost": "ghost-route" },
    providers: [m.provider("good"), m.provider("brokenroute", { script: path.join(m.home, "missing.mjs") }), m.provider("dangling"),
      m.provider("writer", { script: m.writingProvider })],
  });
  const before = m.snapshot();
  const r = m.run();
  const report = doctorReport(r);
  assert.equal(r.status, 1, "blocked → 退出码 1：" + r.stderr);
  assert.equal(report.overall, "blocked");
  assert.equal(checkOf(report, "runtime").ok, false, "没装运行时");
  assert.equal(checkOf(report, "registry").ok, true);
  assert.equal(checkOf(report, "route_without_provider").ok, false);
  assert.match(checkOf(report, "route_without_provider").detail, /lonely/u, "① 要点名没有状态入口的路由");
  // ② 默认**不执行**状态入口脚本：报未探测（unknown），会写盘的 provider 没跑。
  assert.equal(checkOf(report, "provider_runs").ok, null, checkOf(report, "provider_runs").detail);
  assert.match(checkOf(report, "provider_runs").detail, /未探测.*--probe-providers/u);
  assert.equal(fs.existsSync(m.marker), false, "**默认不执行状态入口脚本**");
  assert.equal(checkOf(report, "session_route_missing").ok, false);
  assert.match(checkOf(report, "session_route_missing").detail, /ghost-route/u, "③ 要点名指向不存在路由的话题登记");
  assert.equal(checkOf(report, "provider_without_route").ok, false);
  assert.match(checkOf(report, "provider_without_route").detail, /dangling/u, "④ 要点名指向不存在路由的状态入口");
  assert.equal(checkOf(report, "binding_expiry").ok, false);
  assert.match(checkOf(report, "binding_expiry").detail, /即将到期：bad（3 天）/u, "⑤ 阈值 7 天内要点名并给天数：" + checkOf(report, "binding_expiry").detail);
  assert.match(checkOf(report, "binding_expiry").detail, /待认领代际已过期：bad/u);
  assert.match(checkOf(report, "binding_expiry").detail, /已过期：gone/u, "⑤ 已过期要单独点名，不许折成说不清");
  assert.doesNotMatch(checkOf(report, "binding_expiry").detail, /查不清：gone/u);
  assert.match(checkOf(report, "binding_expiry").detail, /查不清：weird（解析层判 invalid：/u, "⑤ 解析层判 invalid 的不许从日期推出通过：" + checkOf(report, "binding_expiry").detail);
  assert.doesNotMatch(checkOf(report, "binding_expiry").detail, /good/u, "没问题的项目不点名");
  const backlog = checkOf(report, "backlog_vs_publisher");
  assert.equal(backlog.ok, null, "沙箱里查不了 launchctl：有积压时只能 unknown，不许折成 pass 或 fail：" + backlog.detail);
  assert.match(backlog.detail, /积压 2 条：bad（outbox 2 条）/u, backlog.detail);
  assert.match(backlog.detail, /沙箱/u);
  assert.equal(checkOf(report, "codex_drain").ok, null);
  // next 只给预览形式。
  assert.ok(report.next.length > 0);
  for (const n of report.next) assert.equal(/--apply(?!\))/u.test(n.replace(/自行加 --apply/u, "")), false, "**next 不许带 --apply**：" + n);
  // 不泄露 locator：根消息 id、完整 session id。
  const text = JSON.stringify(report);
  assert.equal(text.includes("om_root_bad"), false); assert.equal(text.includes("session_ghostghost"), false, "session id 只留前 8 位");
  // 只读：整棵 HOME 字节一致。
  assert.equal(m.snapshot(), before, "**doctor 一个字节都不许改**");
  // 文本渲染：标记与结论。
  const t = m.run({}, []);
  assert.equal(t.status, 1);
  assert.match(t.stdout, /✗ ① route 有状态入口/u); assert.match(t.stdout, /结论：blocked/u); assert.match(t.stdout, /下一步（都是预览形式/u);
  // 未知参数拒绝。
  assert.equal(m.run({}, ["--fix"]).status, 1);
  // 显式 --probe-providers：执行状态入口脚本 —— ② 才能 fail 并点名；会写盘的那个确实写了（边界明说）。
  const probed = doctorReport(m.run({}, ["--json", "--probe-providers"]));
  assert.equal(checkOf(probed, "provider_runs").ok, false);
  assert.match(checkOf(probed, "provider_runs").detail, /brokenroute/u, "② 要点名跑不起来的状态入口");
  assert.equal(fs.existsSync(m.marker), true, "加了 --probe-providers 才会执行状态入口脚本");
  // ⑤ 只有解析不清、没有 fail 时是 unknown，不是 pass。
  const m2 = doctorMachine();
  const w2 = m2.project("weird", { expiresAt: "2099-01-01T00:00:00.000Z", invalidTopicState: true });
  m2.writeTables({ projects: [{ id: "weird", root: w2, root_message_id: "om_x", status: "active", expires_at: "2099-01-01T00:00:00.000Z" }] });
  assert.equal(checkOf(doctorReport(m2.run()), "binding_expiry").ok, null, "**invalid 不许折成 pass**");
});

test("doctor：runDoctor({home}) 的三张表路径与 Codex 子进程环境都从同一份 home 派生（进程内）", () => {
  const m = doctorMachine();
  const good = m.project("good", { expiresAt: "2099-01-01T00:00:00.000Z" });
  // 三张表放在 home 的默认位置，不设任何环境变量覆盖。
  const bridge = path.join(m.home, ".claude", "feishu-bridge");
  fs.mkdirSync(bridge, { recursive: true });
  fs.writeFileSync(path.join(bridge, "registry.json"), JSON.stringify({ schema_version: "1.0", projects: [{ id: "good", root: good, root_message_id: "om_x", status: "active", expires_at: "2099-01-01T00:00:00.000Z" }] }));
  fs.writeFileSync(path.join(bridge, "routes.json"), JSON.stringify({ routes: [m.route("good")], sessions: {} }));
  fs.writeFileSync(path.join(bridge, "status-providers.json"), JSON.stringify({ providers: [m.provider("good")] }));
  const saved = {};
  for (const k of ["FEISHU_BRIDGE_REGISTRY", "FEISHU_BRIDGE_ROUTES", "FEISHU_BRIDGE_STATUS_PROVIDERS", "CODEX_HOME", "FEISHU_CODEX_BRIDGE_HOME"]) { saved[k] = process.env[k]; delete process.env[k]; }
  let report;
  try { report = runDoctor({ home: m.home }); }
  finally { for (const [k, v] of Object.entries(saved)) if (v !== undefined) process.env[k] = v; }
  assert.equal(checkOf(report, "registry").detail, "已登记 1 个项目", "登记表要从传入的 home 派生，不是当前机器的");
  assert.equal(checkOf(report, "provider_runs").ok, null, "**进程内调用默认也不执行状态入口脚本**");
  // 显式 home 不是当前用户的家目录 = 沙箱：没注入 launchctl 就不许探测当前机器的 launchd（两侧都报沙箱）。
  const late = m.project("late", { expiresAt: "2099-01-01T00:00:00.000Z", outboxPending: 1 });
  fs.writeFileSync(path.join(bridge, "registry.json"), JSON.stringify({ schema_version: "1.0", projects: [
    { id: "good", root: good, root_message_id: "om_x", status: "active", expires_at: "2099-01-01T00:00:00.000Z" },
    { id: "late", root: late, root_message_id: "om_y", status: "active", expires_at: "2099-01-01T00:00:00.000Z" }] }));
  let report2;
  for (const k of Object.keys(saved)) delete process.env[k];
  try { report2 = runDoctor({ home: m.home }); }
  finally { for (const [k, v] of Object.entries(saved)) if (v !== undefined) process.env[k] = v; }
  assert.equal(checkOf(report2, "backlog_vs_publisher").ok, null, checkOf(report2, "backlog_vs_publisher").detail);
  assert.match(checkOf(report2, "backlog_vs_publisher").detail, /沙箱/u, "**显式 home 不是家目录就是沙箱，不碰真实 launchctl**：" + checkOf(report2, "backlog_vs_publisher").detail);
  assert.match(checkOf(report2, "codex_drain").detail, /沙箱/u);
  assert.equal(checkOf(report, "route_without_provider").ok, true);
  assert.deepEqual(machineContext({ home: m.home }).codexEnv.CODEX_HOME, path.join(m.home, ".codex"), "Codex 子进程环境同样从 home 派生");
});

test("doctor：好机器 —— 全部 pass、退出码 0；沙箱里不注入 launchctl 则 incomplete、退出码 2（真实进程）", () => {
  const m = doctorMachine({ installRuntime: true });
  const good = m.project("good", { expiresAt: "2099-01-01T00:00:00.000Z" });
  m.writeTables({
    projects: [{ id: "good", root: good, root_message_id: "om_root_good", status: "active", expires_at: "2099-01-01T00:00:00.000Z" }],
    // 好机器的默认路由处理器就是装好的运行时（issue #88 之后 ⑦ 要查这个）
    routes: [{ ...m.route("self"), handler: path.join(m.home, ".claude", "feishu-bridge", "runtime", "current", "scripts", "inbound.mjs"), default: true }],
    sessions: { "session_aaaaaaaaaaaa": "self" }, providers: [m.provider("self")],
  });
  // 沙箱、没注入 launchctl：兜底定时器两项都 unknown → incomplete、退出码 2，但没有一项 fail。
  const r2 = m.run();
  const rep2 = doctorReport(r2);
  assert.equal(checkOf(rep2, "default_route_handler").ok, true, checkOf(rep2, "default_route_handler").detail);
  assert.equal(r2.status, 2, "incomplete → 退出码 2：" + r2.stderr);
  assert.equal(rep2.overall, "incomplete");
  assert.equal(rep2.checks.some((c) => c.ok === false), false, JSON.stringify(rep2.checks.filter((c) => c.ok === false)));
  assert.equal(checkOf(rep2, "runtime").ok, true, checkOf(rep2, "runtime").detail);
  assert.equal(checkOf(rep2, "backlog_vs_publisher").ok, true, "无积压时不依赖发布器状态：" + checkOf(rep2, "backlog_vs_publisher").detail);
  assert.equal(checkOf(rep2, "codex_drain").ok, null);
  // 注入 launchctl（测试隔离点）：Claude 兜底已加载；Codex 侧 plist 与 launchd 输出都按其判据造真 → 全 pass、ready、退出码 0。
  const gen = spawnSync(process.execPath, ["--input-type=module", "-e",
    'import fs from "node:fs"; import path from "node:path"; const m = await import(process.argv[1]);' +
    'const home = process.env.HOME; const file = m.plistPath(home); fs.mkdirSync(path.dirname(file), { recursive: true });' +
    'fs.writeFileSync(file, m.plistBody({ home })); process.stdout.write(JSON.stringify({ expect: m.expectedJob({ home }), label: m.LAUNCH_LABEL }));',
    pathToFileURL(path.resolve("scripts", "codex", "drain-service.mjs")).href],
    { encoding: "utf-8", env: { ...process.env, HOME: m.home, CODEX_HOME: path.join(m.home, ".codex") } });
  assert.equal(gen.status, 0, gen.stderr);
  const { expect, label } = JSON.parse(gen.stdout);
  const claudeJob = claudeDrainExpectedJob({ home: m.home });
  const fake = path.join(m.home, "fake-launchctl.mjs");
  fs.writeFileSync(fake, [
    "const [cmd, label] = process.argv.slice(2);",
    "if (cmd !== \"list\") process.exit(1);",
    "if (label === " + JSON.stringify(label) + ") { process.stdout.write('{ \"Program\" = \"" + expect.node + "\"; \"ProgramArguments\" = ( " + expect.args.map((a) => '\\"' + a + '\\"').join("; ") + "; ); };'); process.exit(0); }",
    "if (label === " + JSON.stringify(CLAUDE_DRAIN_LAUNCH_LABEL) + ") { process.stdout.write('{ \"Program\" = \"" + claudeJob.node + "\"; \"ProgramArguments\" = ( " + claudeJob.args.map((a) => '\\"' + a + '\\"').join("; ") + "; ); };'); process.exit(0); }",
    "process.stderr.write('Could not find service'); process.exit(113);",
  ].join("\n"));
  const wrapper = path.join(m.home, "launchctl");
  fs.writeFileSync(wrapper, "#!/bin/sh\nexec " + JSON.stringify(process.execPath) + " " + JSON.stringify(fake) + " \"$@\"\n", { mode: 0o755 });
  const before = m.snapshot();
  // ready 需要 ② 也 pass —— 显式 --probe-providers（这里的 provider 只打印）。
  const r = m.run({ FEISHU_BRIDGE_LAUNCHCTL: wrapper }, ["--json", "--probe-providers"]);
  const report = doctorReport(r);
  assert.equal(report.overall, "ready", JSON.stringify(report.checks.filter((c) => c.ok !== true)));
  assert.equal(r.status, 0);
  assert.equal(checkOf(report, "codex_drain").ok, true, checkOf(report, "codex_drain").detail);
  assert.match(checkOf(report, "backlog_vs_publisher").detail, /已加载/u);
  assert.deepEqual(report.next, []);
  assert.equal(m.snapshot(), before, "只读");
  assert.match(m.run({ FEISHU_BRIDGE_LAUNCHCTL: wrapper }, ["--probe-providers"]).stdout, /结论：ready/u);
  // 注入了 launchctl，但 Codex 侧 plist 不在、launchd 也没它 → Codex 体检说"未启用"（ok null）→ 这里必须也是 unknown，不许折成 pass。
  fs.rmSync(JSON.parse(gen.stdout).expect ? path.join(m.home, "Library", "LaunchAgents", label + ".plist") : "", { force: true });
  fs.writeFileSync(fake, fs.readFileSync(fake, "utf-8").replace("if (label === " + JSON.stringify(label) + ")", "if (false)"));
  const rAbsent = doctorReport(m.run({ FEISHU_BRIDGE_LAUNCHCTL: wrapper }));
  assert.equal(checkOf(rAbsent, "codex_drain").ok, null, "**Codex 侧未启用 = 查不清，不是 pass**：" + checkOf(rAbsent, "codex_drain").detail);
  assert.equal(rAbsent.overall, "incomplete");
  // 同一台机器，兜底定时器没加载 + 有积压 → ⑥ fail（不是 unknown）。
  const bad = m.project("late", { expiresAt: "2099-01-01T00:00:00.000Z", outboxPending: 1 });
  m.writeTables({
    projects: [{ id: "good", root: good, root_message_id: "om_root_good", status: "active", expires_at: "2099-01-01T00:00:00.000Z" },
      { id: "late", root: bad, root_message_id: "om_root_late", status: "active", expires_at: "2099-01-01T00:00:00.000Z" }],
    routes: [m.route("good")], sessions: {}, providers: [m.provider("good")],
  });
  // 同名 job 在，但跑的是 /bin/echo（评审探针）→ loaded_other → ⑥ fail，不许说成"积压有人发"。
  const claudeBranch = fs.readFileSync(fake, "utf-8").split("\n").find((l) => l.includes(JSON.stringify(CLAUDE_DRAIN_LAUNCH_LABEL)));
  fs.writeFileSync(fake, fs.readFileSync(fake, "utf-8").replace(claudeBranch,
    "if (label === " + JSON.stringify(CLAUDE_DRAIN_LAUNCH_LABEL) + ") { process.stdout.write('{ \"Program\" = \"/bin/echo\"; \"ProgramArguments\" = ( \"/bin/echo\"; \"hi\"; ); };'); process.exit(0); }"));
  const rOther = doctorReport(m.run({ FEISHU_BRIDGE_LAUNCHCTL: wrapper }));
  assert.equal(checkOf(rOther, "backlog_vs_publisher").ok, false, "**同名 job 跑别的程序不算在发**：" + checkOf(rOther, "backlog_vs_publisher").detail);
  assert.match(checkOf(rOther, "backlog_vs_publisher").detail, /参数不是当前这份/u);
  // 明确没有这个 job（plist 写了没加载）→ ⑥ fail。
  fs.writeFileSync(fake, fs.readFileSync(fake, "utf-8").split("\n").filter((l) => !l.includes(JSON.stringify(CLAUDE_DRAIN_LAUNCH_LABEL))).join("\n"));
  const r3 = doctorReport(m.run({ FEISHU_BRIDGE_LAUNCHCTL: wrapper }));
  assert.equal(checkOf(r3, "backlog_vs_publisher").ok, false, checkOf(r3, "backlog_vs_publisher").detail);
  assert.match(checkOf(r3, "backlog_vs_publisher").detail, /积压 1 条：late（outbox 1 条）；兜底定时器 .*没被 launchd 加载/u);
  assert.equal(r3.overall, "blocked");
});

test("claim 写原语：扩展对象覆盖不了固定身份字段", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-claimfix-"));
  const r = acquireClaim({ claimsDir: dir, messageId: "om_1", logicalTaskKey: "k",
    meta: { claim_key: "伪造", state: "handed_off", message_id: "om_别人", claimed_at: "刚才", extra: 1 } });
  assert.equal(r.ok, true);
  const claim = JSON.parse(fs.readFileSync(path.join(dir, r.key + ".claim", "claim.json"), "utf-8"));
  assert.equal(claim.claim_key, r.key); assert.equal(claim.state, "claimed");
  assert.equal(claim.message_id, "om_1"); assert.ok(isCanonicalIso(claim.claimed_at));
  assert.equal(claim.extra, 1, "非保留键照常保留");
  const f = recordClaimState({ claimsDir: dir, key: r.key, state: "failed",
    detail: { claim_key: "伪造", state: "completed", recorded_at: "刚才", reason: "x" } });
  const rec = JSON.parse(fs.readFileSync(f, "utf-8"));
  assert.equal(rec.claim_key, r.key); assert.equal(rec.state, "failed");
  assert.ok(isCanonicalIso(rec.recorded_at)); assert.equal(rec.reason, "x");
});

test("Claude watcher：期望身份对不上或缺席 → 启动期拒绝，零终态落盘、零 Dialogue 收口（真实进程）", () => {
  // 评审实测：错的 logical task 最终 exit 2，磁盘上却同时留下 handed_off 与 failed ——
  // 核对发生在终态副作用之后。现在一切核验在启动期。
  const cases = [
    ["binding 对不上", (base) => ({ ...base, FEISHU_BRIDGE_EXPECT_BINDING_ID: "别的 binding" }), /binding_id/u],
    ["session 对不上", (base) => ({ ...base,
      FEISHU_BRIDGE_EXPECT_CLAUDE_SESSION_ID: "01911111-2222-7333-8444-555555555555" }), /claude_session_id/u],
    ["期望身份缺席", () => ({}), /缺少 inbound 传入的期望身份/u],
  ];
  for (const [why, envOf, pattern] of cases) {
    const h = watcherMatrixRunner.fixture();
    const env = envOf(expectEnvFor(h.dir));
    const rt = path.join(h.dir, ".runtime-data", "inbound");
    const claims = path.join(rt, "delivery-claims");
    const key = claimKeyFor("ident-" + why);
    fs.writeFileSync(path.join(rt, "runs", key + ".jsonl"),
      JSON.stringify({ type: "result", is_error: false, result: "这一轮的结果" }) + "\n");
    writeClaimFixture({ claimsDir: claims, key, root: h.dir });
    const lock = path.join(rt, "session.lock");
    fs.mkdirSync(lock, { recursive: true });
    const r = spawnSync(process.execPath,
      [path.resolve("scripts", "watch-and-publish.mjs"), key, h.dir],
      { encoding: "utf-8", env: { ...process.env, ...env, HOME: h.dir }, timeout: 60_000 });
    assert.equal(r.status, 2, why + "：" + r.stderr);
    assert.match(r.stderr, pattern, why);
    assert.equal(fs.existsSync(path.join(claims, key + ".handed_off.json")), false,
      why + "：**核对之前不许落 handed_off**");
    assert.equal(fs.existsSync(path.join(rt, "runs", key + ".published.json")), false, why + "：不许发");
    assert.equal(fs.existsSync(lock), true, why + "：锁不动");
    const files = fs.readdirSync(claims).filter((f) => f.startsWith(key + "."));
    assert.deepEqual(files.filter((f) => f !== key + ".claim"),
      why === "期望身份缺席" ? [] : [key + ".failed.json"],
      why + "：只许留一份 failed 证据（缺期望身份时连它也不写 —— 没做任何路径派生）");
  }
});

test("run 通道并发互斥：两个 watcher 同一 run，只许发出一张（真实进程）", () => {
  // 评审实测：只有"发送后回执"时，两个并发 watcher 同时读到 shouldPublish、
  // 各发一张 —— 真实双发。发布前原子 claim 才互斥得住。
  //
  // test() 基座是同步的（fn() 不 await）—— 异步测试会假通过。
  // 并发编排放进子进程编排器，本体保持同步。
  const h = watcherMatrixRunner.fixture();
  const lockDir = path.join(h.dir, ".runtime-data", "outbound", "publish.lock");
  fs.mkdirSync(path.dirname(lockDir), { recursive: true });
  assert.equal(acquirePublishLock(lockDir).ok, true, "锁一直被占：两边都走预算耗尽那条路");
  try {
    const runs = path.join(h.dir, ".runtime-data", "inbound", "runs");
    const key = claimKeyFor("9");
    fs.writeFileSync(path.join(runs, key + ".jsonl"),
      JSON.stringify({ type: "result", is_error: false, result: "并发那一轮" }) + "\n");
    const orchestrator = path.join(h.dir, "orchestrate.mjs");
    fs.writeFileSync(orchestrator, [
      'import { spawn } from "node:child_process";',
      'const [watcher, key, dir] = process.argv.slice(2);',
      'const one = () => new Promise((resolve) => {',
      '  const c = spawn(process.execPath, [watcher, key, dir],',
      '    { env: { ...process.env }, stdio: ["ignore", "pipe", "pipe"] });',
      '  let out = "";',
      '  c.stdout.on("data", (d) => { out += d; });',
      '  c.stderr.on("data", (d) => { out += d; });',
      '  c.on("close", (code) => resolve({ code, out }));',
      '});',
      'const [a, b] = await Promise.all([one(), one()]);',
      'console.log(JSON.stringify({ codes: [a.code, b.code], out: a.out + b.out }));',
    ].join("\n"));
    writeClaimFixture({ claimsDir: path.join(h.dir, ".runtime-data", "inbound", "delivery-claims"), key, root: h.dir });
    const r = spawnSync(process.execPath,
      [orchestrator, path.resolve("scripts", "watch-and-publish.mjs"), key, h.dir],
      { encoding: "utf-8", env: { ...process.env, ...expectEnvFor(h.dir), HOME: h.dir,
        FEISHU_BRIDGE_PUBLISH_WAIT_MS: "500" }, timeout: 90_000 });
    assert.equal(r.status, 0, (r.stderr ?? "").slice(0, 300));
    const parsed = JSON.parse((r.stdout ?? "").trim().split("\n").at(-1));
    assert.deepEqual(parsed.codes, [0, 0], parsed.out.slice(0, 300));
    const argsFile = path.join(h.dir, "lark-calls.jsonl");
    const sent = fs.existsSync(argsFile)
      ? fs.readFileSync(argsFile, "utf-8").split("\n").filter((l) => l.includes("并发那一轮")) : [];
    assert.equal(sent.length, 1,
      "**同一条 run 只许发出一张卡** —— 实际发了 " + sent.length + " 张。\n输出：" +
      parsed.out.slice(0, 1200));
    assert.match(parsed.out, /claim 互斥|正在发同一条 run|已由另一个 watcher 送达/u,
      "没发的那个要说清为什么（claim 输了或复核到回执）");
  } finally {
    releasePublishLock(lockDir);
  }
});

test("发布锁 io 故障不是竞争：不套「让给持锁方」的话术（真实进程）", () => {
  // 评审实测：锁目录不可写时被伪装成 busy —— 基础设施故障被说成礼让，
  // 人会去等一个不存在的对手。
  const h = watcherMatrixRunner.fixture();
  h.seed("io 故障时的进展");
  const outbound = path.join(h.dir, ".runtime-data", "outbound");
  const runs = path.join(h.dir, ".runtime-data", "inbound", "runs");
  const key = claimKeyFor("8");
  fs.writeFileSync(path.join(runs, key + ".jsonl"),
    JSON.stringify({ type: "result", is_error: false, result: "io 故障那一轮" }) + "\n");
  // outbound 目录改只读：acquirePublishLock 的 mkdir 直接 io_error。
  fs.chmodSync(outbound, 0o500);
  let r;
  try {
    writeClaimFixture({ claimsDir: path.join(h.dir, ".runtime-data", "inbound", "delivery-claims"), key, root: h.dir });
    r = spawnSync(process.execPath,
      [path.resolve("scripts", "watch-and-publish.mjs"), key, h.dir],
      { encoding: "utf-8", env: { ...process.env, ...expectEnvFor(h.dir), HOME: h.dir,
        FEISHU_BRIDGE_PUBLISH_WAIT_MS: "500" }, timeout: 60_000 });
  } finally {
    fs.chmodSync(outbound, 0o700);
  }
  const said = (r.stdout ?? "") + (r.stderr ?? "");
  assert.match(said, /基础设施故障/u, "**要说是基础设施故障**：" + said.slice(0, 400));
  assert.equal(/让给持锁方/u.test(said), false,
    "**不许把 io 故障说成礼让** —— 人会去等一个不存在的对手");
  // run 结果仍经 claim 单发（claim 在 runs 目录，不受 outbound 只读影响）。
  const argsFile = path.join(h.dir, "lark-calls.jsonl");
  const sent = fs.existsSync(argsFile)
    ? fs.readFileSync(argsFile, "utf-8").split("\n").filter((l) => l.includes("io 故障那一轮")) : [];
  assert.equal(sent.length, 1, "run 结果要经 claim 发出去（claim 与锁不同目录）");
});

test("stale 接管：N 个接管者同抢一份死 PID 的 claim，恰好一个得手", () => {
  // 评审实测：「判 stale → rm → wx」下 64 个接管者出了 3 个 winner；
  // 换 rename 摘除照样击穿（rename 按路径不按 inode，16 并发出 5 个）。
  // 定稿：reap 锁串行接管 + token 代际核对，恰好一个赢。
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-reap-"));
  const runs = path.join(dir, "runs");
  fs.mkdirSync(runs);
  const key = "7".repeat(64);
  // 一份死 PID 的 stale claim（PID 1..99999 里找个必死的：用刚退出的子进程）。
  const dead = spawnSync(process.execPath, ["-e", "process.exit(0)"], { encoding: "utf-8" });
  void dead;
  fs.writeFileSync(path.join(runs, key + ".publish-claim.json"),
    JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z", token: "old" }) + "\n");

  // 编排器：起 N 个子进程，屏障对齐后同时抢，统计 winner 数。
  const orchestrator = path.join(dir, "orchestrate.mjs");
  fs.writeFileSync(orchestrator, [
    'import { spawn } from "node:child_process";',
    'import fs from "node:fs";',
    'const [worker, runs, key, nStr, barrier] = process.argv.slice(2);',
    'const N = Number(nStr);',
    'const children = [];',
    'for (let i = 0; i < N; i += 1) {',
    '  children.push(new Promise((resolve) => {',
    '    const c = spawn(process.execPath, [worker, runs, key, barrier], { stdio: ["ignore", "pipe", "inherit"] });',
    '    let out = "";',
    '    c.stdout.on("data", (d) => { out += d; });',
    '    c.on("close", () => resolve(out.trim()));',
    '  }));',
    '}',
    'setTimeout(() => fs.writeFileSync(barrier, "go"), 300);',
    'const results = await Promise.all(children);',
    'console.log(JSON.stringify(results));',
  ].join("\n"));
  const worker = path.join(dir, "worker.mjs");
  fs.writeFileSync(worker, [
    'import fs from "node:fs";',
    'const [runs, key, barrier] = process.argv.slice(2);',
    'const { claimRunPublish } = await import(' + JSON.stringify(
      pathToFileURL(path.resolve("scripts", "outbound.mjs")).href) + ');',
    'while (!fs.existsSync(barrier)) { /* 自旋对齐，拼同时抢 */ }',
    'const r = claimRunPublish({ runsDir: runs, key });',
    'console.log(r.ok ? "WIN" : "LOSE:" + r.reason);',
    '// **赢了要活着持有一会儿** —— 立刻退出的话 pid 变死，',
    '// 后来者会按崩溃恢复合法接管（那是另一个正确行为，不是这条要测的）。',
    'if (r.ok) await new Promise((res) => setTimeout(res, 4000));',
  ].join("\n"));
  const N = 32;
  const r = spawnSync(process.execPath,
    [orchestrator, worker, runs, key, String(N), path.join(dir, "barrier")],
    { encoding: "utf-8", timeout: 120_000 });
  assert.equal(r.status, 0, (r.stderr ?? "").slice(0, 300));
  const results = JSON.parse((r.stdout ?? "").trim().split("\n").at(-1));
  const winners = results.filter((x) => x === "WIN").length;
  assert.equal(winners, 1,
    "**恰好一个接管者得手** —— 实际 " + winners + " 个（" + N + " 个并发）");
});

test("release 只释放自己的代际：旧 token 删不掉接管者的新 claim", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-token-"));
  const runs = path.join(dir, "runs");
  fs.mkdirSync(runs);
  const key = "6".repeat(64);
  const a = claimRunPublish({ runsDir: runs, key });
  assert.equal(a.ok, true);
  // 旧持有者（或任何不知道现任 token 的人）来释放 —— 必须无效。
  assert.equal(releaseRunPublishClaim({ runsDir: runs, key, token: "not-the-token" }), false,
    "**token 对不上就不许删**");
  assert.equal(fs.existsSync(path.join(runs, key + ".publish-claim.json")), true,
    "claim 必须还在");
  assert.equal(releaseRunPublishClaim({ runsDir: runs, key }), false, "不带 token 也不许删");
  assert.equal(releaseRunPublishClaim({ runsDir: runs, key, token: a.token }), true,
    "现任 token 才放行");
  assert.equal(fs.existsSync(path.join(runs, key + ".publish-claim.json")), false);
});

test("回执三态：损坏回执 fail-closed，不发也不当送达（真实进程）", () => {
  // 评审点名：existsSync 把空文件、坏 JSON、目录都说成"已送达"——
  // 一条 run 结果被永久跳过。说不清送没送达时：发可能双发、跳过可能漏发，
  // 唯一诚实的做法是不发 + 报警 + 留给人核对。
  for (const [why, plant] of [
    ["空文件", (f) => fs.writeFileSync(f, "")],
    ["坏 JSON", (f) => fs.writeFileSync(f, "{ 坏了")],
    ["缺 published_at", (f) => fs.writeFileSync(f, JSON.stringify({ feishu_message_id: "om" }))],
  ]) {
    const h = watcherMatrixRunner.fixture();
    const runs = path.join(h.dir, ".runtime-data", "inbound", "runs");
    const key = claimKeyFor("5");
    fs.writeFileSync(path.join(runs, key + ".jsonl"),
      JSON.stringify({ type: "result", is_error: false, result: "回执坏了那一轮" }) + "\n");
    plant(path.join(runs, key + ".published.json"));
    writeClaimFixture({ claimsDir: path.join(h.dir, ".runtime-data", "inbound", "delivery-claims"), key, root: h.dir });
    const r = spawnSync(process.execPath,
      [path.resolve("scripts", "watch-and-publish.mjs"), key, h.dir],
      { encoding: "utf-8", env: { ...process.env, ...expectEnvFor(h.dir), HOME: h.dir }, timeout: 60_000 });
    const said = (r.stdout ?? "") + (r.stderr ?? "");
    const argsFile = path.join(h.dir, "lark-calls.jsonl");
    const sent = fs.existsSync(argsFile)
      ? fs.readFileSync(argsFile, "utf-8").split("\n").filter((l) => l.includes("回执坏了那一轮")) : [];
    assert.equal(sent.length, 0, why + "：**说不清就不许发**（可能双发）：" + said.slice(0, 300));
    assert.match(said, /回执损坏|说不清送没送达/u, why + "：要报警，不许静默当成已送达");
  }
});

test("过期 reap 锁：两个接管者都必须 fail-closed，不许自愈再抢", () => {
  // 评审固定时序复现过：热路径按 mtime 自愈 reap 锁 → 内层夺锁建新 claim、
  // 外层拿旧核对结果删掉它再建自己的 —— 两个 ok:true。
  // 同一个反模式低一层复发，递归不会收敛。定稿：**reap 锁存在即 fail-closed**。
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-reaplock-"));
  const runs = path.join(dir, "runs");
  fs.mkdirSync(runs);
  const key = "4".repeat(64);
  const claimFile = path.join(runs, key + ".publish-claim.json");
  // 旧 claim（死 PID）+ 一把"过期"的 reap 锁（老 mtime）。
  fs.writeFileSync(claimFile,
    JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z", token: "old" }) + "\n");
  const reapLock = claimFile + ".reaplock";
  fs.writeFileSync(reapLock, JSON.stringify({ pid: 999999998, at: "2020-01-01T00:00:00.000Z" }) + "\n");
  const past = new Date(Date.now() - 3600_000);
  fs.utimesSync(reapLock, past, past);

  for (const who of ["接管者一", "接管者二"]) {
    const r = claimRunPublish({ runsDir: runs, key });
    assert.equal(r.ok, false, who + "：**残留 reap 锁在场就不许得手** —— " + JSON.stringify(r));
    assert.equal(r.reason, "reap_lock_held", who);
    assert.match(r.detail, /repair-run-claim/u, who + "：只许指向显式维护入口");
    assert.equal(/人工删除/u.test(r.detail), false,
      who + "：**不给直接 rm 的旁路** —— 那会绕过维护互斥");
  }
  assert.equal(fs.existsSync(claimFile), true, "旧 claim 一个字都不许动");
  assert.equal(fs.existsSync(reapLock), true, "残留锁也不许在热路径被清");
});

test("回执时间必须是规范时间：非空字符串冒充不了合法送达", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-receipt-iso-"));
  const runs = path.join(dir, "runs");
  fs.mkdirSync(runs);
  const key = "3".repeat(64);
  const file = path.join(runs, key + ".published.json");
  fs.writeFileSync(file, JSON.stringify({ published_at: "不是时间", feishu_message_id: "om" }));
  const r = readRunReceipt({ runsDir: runs, key });
  assert.equal(r.state, "unreadable",
    "**冒充的时间不算送达** —— 否则这条 run 被永久跳过：" + JSON.stringify(r));
  fs.writeFileSync(file, JSON.stringify({ published_at: "2026-08-26T00:00:00.000Z" }));
  assert.equal(readRunReceipt({ runsDir: runs, key }).state, "valid", "规范时间照常放行");
});

test("reap 锁残留：真实 watcher 要给出锁路径与维护命令，维护入口核验后才清（端到端）", () => {
  // 评审实测：detail 里有锁路径和处置提示，watcher 包装层只打一句泛化话 ——
  // run 永久停发却无路可走。闭环三段都要验：报警带路 → 维护核验 → 恢复发布。
  const h = watcherMatrixRunner.fixture();
  const runs = path.join(h.dir, ".runtime-data", "inbound", "runs");
  const key = claimKeyFor("2");
  fs.writeFileSync(path.join(runs, key + ".jsonl"),
    JSON.stringify({ type: "result", is_error: false, result: "被残留锁拦住那一轮" }) + "\n");
  const claimFile = path.join(runs, key + ".publish-claim.json");
  fs.writeFileSync(claimFile,
    JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z", token: "old" }) + "\n");
  const reapLock = claimFile + ".reaplock";
  fs.writeFileSync(reapLock, JSON.stringify({ pid: 999999998, at: "2020-01-01T00:00:00.000Z" }) + "\n");
  const past = new Date(Date.now() - 3600_000);
  fs.utimesSync(reapLock, past, past);

  // ① watcher：不发、报警带上锁路径与维护命令、落持久失败记录。
  writeClaimFixture({ claimsDir: path.join(h.dir, ".runtime-data", "inbound", "delivery-claims"), key, root: h.dir });
  const r1 = spawnSync(process.execPath,
    [path.resolve("scripts", "watch-and-publish.mjs"), key, h.dir],
    { encoding: "utf-8", env: { ...process.env, ...expectEnvFor(h.dir), HOME: h.dir }, timeout: 60_000 });
  const said = (r1.stdout ?? "") + (r1.stderr ?? "");
  const argsFile = path.join(h.dir, "lark-calls.jsonl");
  const sentEarly = fs.existsSync(argsFile)
    ? fs.readFileSync(argsFile, "utf-8").split("\n").filter((l) => l.includes("被残留锁拦住那一轮")) : [];
  assert.equal(sentEarly.length, 0, "残留锁在场不许发");
  assert.match(said, /reaplock/u, "**锁路径要在输出里** —— 人得知道删哪个：" + said.slice(0, 300));
  assert.match(said, /repair-run-claim\.mjs/u, "**要指路显式维护命令**");
  const cmdLine = said.split("\n").map((l) => l.trim())
    .find((l) => l.startsWith("node ") && l.includes("repair-run-claim.mjs")) ?? "";
  assert.ok(cmdLine !== "", "要有可执行命令行");
  assert.equal(cmdLine.includes("--apply"), false,
    "**提示的命令行不许带 --apply** —— 说默认预览却给带 --apply 的命令是教人跳过预览：" + cmdLine);
  assert.match(said, new RegExp("--key " + key, "u"), "要带 --key 只清这一条的残留");
  const failRecord = JSON.parse(fs.readFileSync(path.join(runs, key + ".publish-failed.json"), "utf-8"));
  assert.equal(failRecord.reason, "reap_lock_held", "要落持久失败记录");

  // ② 维护入口：**只清 reap 锁，claim 一个字不动**（"判死 → 删 claim"被评审
  // 固定时序击穿过：热路径抢先接管后，维护者按旧结论删掉新 claim）。
  // 预览真的零改盘；活持有者不动；--apply 才清死锁。
  const preview = repairRunClaims({ runsDir: runs, all: true });
  assert.equal(preview.apply, false);
  assert.equal(fs.existsSync(reapLock), true, "**预览零改盘** —— reap 锁还在");
  assert.equal(fs.existsSync(claimFile), true, "claim 也在");
  assert.ok(preview.actions.some((a) => a.action === "would_remove"), JSON.stringify(preview.actions));

  // 活持有者的 reap 锁不许动。
  const liveKey = "1".repeat(64);
  const liveReap = path.join(runs, liveKey + ".publish-claim.json.reaplock");
  fs.writeFileSync(liveReap, JSON.stringify({ pid: process.pid, at: new Date().toISOString() }) + "\n");
  const report = repairRunClaims({ runsDir: runs, all: true, apply: true });
  const keptLive = report.actions.find((a) => a.file.startsWith(liveKey));
  assert.equal(keptLive.action, "kept", "**活持有者一律不动**：" + JSON.stringify(keptLive));
  assert.equal(fs.existsSync(liveReap), true);
  assert.equal(fs.existsSync(reapLock), false, "死 reap 锁要被清掉");
  assert.equal(fs.existsSync(claimFile), true,
    "**死 claim 不由维护入口删** —— 留给热路径接管协议自取（32 并发回归钉过恰好一个）");
  fs.rmSync(liveReap, { force: true });

  // ③ 清理 reap 锁之后，watcher 经协议接管死 claim、恢复发布。
  writeClaimFixture({ claimsDir: path.join(h.dir, ".runtime-data", "inbound", "delivery-claims"), key, root: h.dir });
  const r2 = spawnSync(process.execPath,
    [path.resolve("scripts", "watch-and-publish.mjs"), key, h.dir],
    { encoding: "utf-8", env: { ...process.env, ...expectEnvFor(h.dir), HOME: h.dir }, timeout: 60_000 });
  void r2;
  const sent = fs.readFileSync(argsFile, "utf-8").split("\n")
    .filter((l) => l.includes("被残留锁拦住那一轮"));
    assert.equal(sent.length, 1, "**维护后要恢复发布** —— 恢复入口不是摆设");
});

test("维护 CLI 是破坏性命令：白名单之外一个参数都不收", () => {
  // 评审实测：includes("--apply") 全数组扫法把 `--unknown -- --apply` 也当授权，
  // 未知参数静默接受、照删、exit 0。
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-repaircli-"));
  const runs = path.join(dir, ".runtime-data", "inbound", "runs");
  fs.mkdirSync(runs, { recursive: true });
  const reap = path.join(runs, "0".repeat(64) + ".publish-claim.json.reaplock");
  fs.writeFileSync(reap, JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z" }) + "\n");
  const cli = (args) => spawnSync(process.execPath,
    [path.resolve("scripts", "repair-run-claim.mjs"), ...args], { encoding: "utf-8" });

  for (const [why, args] of [
    ["未知参数", ["--project", dir, "--unknown-option"]],
    ["-- 透传", ["--project", dir, "--", "--apply"]],
    ["裸参数", ["--project", dir, "extra"]],
    ["key 形状不对", ["--project", dir, "--key", "k1", "--apply"]],
  ]) {
    const r = cli(args);
    assert.notEqual(r.status, 0, why + "：必须拒绝 —— " + (r.stdout ?? ""));
    assert.equal(fs.existsSync(reap), true, why + "：**拒绝时一个文件都不许动**");
  }
  // **核心函数自己也守范围不变量，且参数类型是封闭联合** ——
  // 绕过 CLI 直接调必须被拒、零动作。评审探针：all:"false"/0/{}、
  // key:[合法hex]、apply:"false" 全都曾 ok:true 照删。
  for (const [why, args] of [
    ["没给范围", { apply: true }],
    ["all 是字符串 \"false\"", { all: "false", apply: true }],
    ["all 是 0", { all: 0, apply: true }],
    ["all 是对象", { all: {}, apply: true }],
    ["all 是数组", { all: [], apply: true }],
    ["key 是数组包 hex", { key: ["0".repeat(64)], apply: true }],
    ["apply 是字符串 \"false\"", { all: true, apply: "false" }],
    ["范围给了两个", { key: "0".repeat(64), all: true, apply: true }],
  ]) {
    const direct = repairRunClaims({ runsDir: runs, ...args });
    assert.equal(direct.ok, false, why + "：**必须拒绝** —— " + JSON.stringify(direct));
    assert.equal(fs.existsSync(reap), true, why + "：零动作");
  }
  // 缺值 / flag 当值 / 重复参数 —— 都在任何文件操作之前拒绝。
  // **给"flag 被当成路径"造一个真靶**：名为 --key 的目录里放一把死锁。
  // 光断言退出码不够 —— 假值路径读不了也会非 0，变异照样绿（实测）。
  const flagRuns = path.join(dir, "--key", ".runtime-data", "inbound", "runs");
  fs.mkdirSync(flagRuns, { recursive: true });
  const flagLock = path.join(flagRuns, "0".repeat(64) + ".publish-claim.json.reaplock");
  fs.writeFileSync(flagLock, JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z" }) + "\n");
  {
    const r = spawnSync(process.execPath,
      [path.resolve("scripts", "repair-run-claim.mjs"), "--project", "--key", "--all", "--apply"],
      { encoding: "utf-8", cwd: dir });
    assert.notEqual(r.status, 0, "--project 缺值必须拒绝");
    assert.equal(fs.existsSync(flagLock), true,
      "**名为 --key 的目录里的锁一根毫毛都不许动** —— flag 被当路径就会删到这");
  }
  for (const [why, args] of [
    ["--project 缺值（把 --key 当路径）", ["--project", "--key", "--all", "--apply"]],
    ["--key 缺值", ["--project", dir, "--key", "--apply"]],
    ["重复 --project", ["--project", dir, "--project", dir, "--all"]],
    ["重复 --apply", ["--project", dir, "--all", "--apply", "--apply"]],
  ]) {
    const r = cli(args);
    assert.notEqual(r.status, 0, why + "：必须拒绝 —— " + (r.stdout ?? ""));
    assert.equal(fs.existsSync(reap), true, why + "：零动作");
  }
  // **范围必须显式**：不带 --key/--all 拒绝；两个都带也拒绝。
  for (const [why, args] of [
    ["没给范围", ["--project", dir]],
    ["范围给了两个", ["--project", dir, "--key", "0".repeat(64), "--all"]],
  ]) {
    const r = cli(args);
    assert.notEqual(r.status, 0, why + "：必须拒绝");
    assert.equal(fs.existsSync(reap), true, why + "：零动作");
  }
  // **--key 是精确目标**：<key>f 的邻居不许被顺带删掉。
  const neighbor = path.join(runs, "0".repeat(64) + "f".padEnd(1, "f") + ".publish-claim.json.reaplock");
  fs.writeFileSync(neighbor, JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z" }) + "\n");
  const exact = cli(["--project", dir, "--key", "0".repeat(64), "--apply"]);
  assert.equal(exact.status, 0, exact.stderr);
  assert.equal(fs.existsSync(reap), false, "点名的那个要清掉");
  assert.equal(fs.existsSync(neighbor), true, "**前缀邻居一根毫毛都不许动**");
  fs.rmSync(neighbor, { force: true });

  // 正路：--all 预览不删、--apply 删。
  fs.writeFileSync(reap, JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z" }) + "\n");
  const p1 = cli(["--project", dir, "--all"]);
  assert.equal(p1.status, 0, p1.stderr);
  assert.match(p1.stdout, /dry-run/u);
  assert.equal(fs.existsSync(reap), true, "预览零改盘");
  const p2 = cli(["--project", dir, "--all", "--apply"]);
  assert.equal(p2.status, 0, p2.stderr);
  assert.equal(fs.existsSync(reap), false, "--apply 才清");

  // **维护互斥**：维护锁在场 → fail-closed 零动作（不自愈，指路人工）。
  fs.writeFileSync(reap, JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z" }) + "\n");
  fs.writeFileSync(path.join(runs, ".repair-maintenance.lock"), "{}");
  const held = cli(["--project", dir, "--all", "--apply"]);
  assert.notEqual(held.status, 0, "维护锁在场必须拒绝");
  assert.match((held.stderr ?? ""), /维护互斥|人工删除/u);
  assert.equal(fs.existsSync(reap), true, "**互斥时零动作**");
});

test("维护提示的命令要经得起真 shell：含空格中文引号的项目路径原样可用", () => {
  // 评审要求的形状：从 watcher 输出提取完整命令，经真 shell 执行 dry-run，
  // 再追加 --apply 验证精确目标。源码断言 shellQuote 在不在是"守卫的样子"，
  // 真 shell 跑过才算数 —— 这条线上被路径坑过不止一次。
  const base = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-nasty-"));
  const root = path.join(base, "有 空格'引号的 目录");
  const rt = path.join(root, ".runtime-data", "inbound");
  const runs = path.join(rt, "runs");
  const obDir = path.join(root, ".runtime-data", "outbound", "outbox");
  for (const d of [rt, runs, path.join(rt, "delivery-claims"), obDir]) {
    fs.mkdirSync(d, { recursive: true });
  }
  const bin = path.join(base, "fake-lark.cjs");
  fs.writeFileSync(bin, "#!" + process.execPath + "\n" +
    "process.stdout.write('{\"ok\":true,\"data\":{\"message_id\":\"om\"}}');\n", { mode: 0o700 });
  fs.writeFileSync(path.join(rt, "chain-config.json"), JSON.stringify({
    project_dir: root, logical_task_key: "k", project_display_name: "P",
    task_display_name: "P", lark_cli_bin: bin, auto_publish_on_completion: true }));
  fs.writeFileSync(path.join(rt, "active-mapping.json"), JSON.stringify({
    status: "active", root_message_id: "om_fixture", claude_session_id: null,
    channel_generation_id: "gen-1", expires_at: "2099-01-01T00:00:00.000Z" }));
  const key = claimKeyFor("0");
  fs.writeFileSync(path.join(runs, key + ".jsonl"),
    JSON.stringify({ type: "result", is_error: false, result: "路径刁钻那一轮" }) + "\n");
  const claimFile = path.join(runs, key + ".publish-claim.json");
  fs.writeFileSync(claimFile,
    JSON.stringify({ pid: 999999999, at: "2020-01-01T00:00:00.000Z", token: "old" }) + "\n");
  const reapLock = claimFile + ".reaplock";
  fs.writeFileSync(reapLock, JSON.stringify({ pid: 999999998, at: "2020-01-01T00:00:00.000Z" }) + "\n");
  const past = new Date(Date.now() - 3600_000);
  fs.utimesSync(reapLock, past, past);

  writeClaimFixture({ claimsDir: path.join(root, ".runtime-data", "inbound", "delivery-claims"), key, root: root });
  const r1 = spawnSync(process.execPath,
    [path.resolve("scripts", "watch-and-publish.mjs"), key, root],
    { encoding: "utf-8", env: { ...process.env, ...expectEnvFor(root), HOME: root }, timeout: 60_000 });
  const said = (r1.stdout ?? "") + (r1.stderr ?? "");
  // detail 行也提到入口名 —— 只认以 node 开头的那行命令。
  const cmdLine = (said.split("\n").map((l) => l.trim())
    .find((l) => l.startsWith("node ") && l.includes("repair-run-claim.mjs")) ?? "");
  assert.ok(cmdLine !== "", "要给出完整可执行命令：" + said.slice(0, 300));

  // 真 shell 跑 dry-run：路径里的空格中文引号都不许把命令拆散。
  const dry = spawnSync("/bin/sh", ["-c", cmdLine], { encoding: "utf-8" });
  assert.equal(dry.status, 0, "**照抄的命令必须能跑**：" + (dry.stderr ?? "") + cmdLine);
  assert.match(dry.stdout, /dry-run/u, "默认必须是预览");
  assert.equal(fs.existsSync(reapLock), true, "预览零改盘");

  // 追加 --apply：精确清掉点名那把锁，claim 不动。
  const applied = spawnSync("/bin/sh", ["-c", cmdLine + " --apply"], { encoding: "utf-8" });
  assert.equal(applied.status, 0, applied.stderr);
  assert.equal(fs.existsSync(reapLock), false, "点名的 reap 锁要清掉");
  assert.equal(fs.existsSync(claimFile), true, "claim 由热路径协议自取，维护不碰");
});

test("发布写原语限制生产调用面：落标与失败记账只许事务碰（原始扫描）", () => {
  // R2 收官：四份实现都走事务之后，**限制低层写原语的生产调用面**
  //（它们仍公开导出 —— 事务和测试要用；"收私有"指的是调用面，不是导出面）。
  // "太容易被绕过的 API"正是四个入口各漏一角的土壤（计划文档 §0）。
  // 与 R1 的字段扫描同一形状：精确路径豁免、原始扫描不解析注释。
  const tokens = ["markSent", "recordPublishFailure"];
  const exempt = new Set([
    "outbox.mjs",             // 定义处
    "publish-attempt.mjs",    // 唯一的合法调用方（事务）
    "test.mjs", path.join("codex", "test.mjs"),
    path.join("test-support", "publish-matrix.mjs"),   // 夹具用真实写入器造已暂停记录
  ]);
  const offenders = [];
  let scanned = 0;
  const walk = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) { walk(full); continue; }
      if (!entry.name.endsWith(".mjs")) continue;
      const rel = path.relative(path.resolve("scripts"), full);
      if (exempt.has(rel)) continue;
      scanned += 1;
      const text = fs.readFileSync(full, "utf-8");
      for (const t of tokens) if (text.includes(t)) offenders.push(rel + " ← " + t);
    }
  };
  walk(path.resolve("scripts"));
  assert.deepEqual(offenders, [],
    "这些文件绕过事务直接碰发布写原语（或在注释里留了名字诱人照抄）");
  assert.ok(scanned >= 60, "扫描面缩水了：" + scanned);
  // 自证有效：豁免之外种一个违规必须被抓 —— 夹具树验证。
  // **两个 token 全种、期望字面写死** —— 只种一个的话，token 列表缩水
  // 照样绿（R1 那次期望自我引用的同款教训）。
  const fixture = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-primscan-"));
  fs.writeFileSync(path.join(fixture, "sneak.mjs"),
    "const x = markSent; const y = recordPublishFailure;\n");
  const proofOffenders = [];
  for (const entry of fs.readdirSync(fixture, { withFileTypes: true })) {
    const text = fs.readFileSync(path.join(fixture, entry.name), "utf-8");
    for (const t of tokens) if (text.includes(t)) proofOffenders.push(entry.name + " ← " + t);
  }
  assert.deepEqual(proofOffenders,
    ["sneak.mjs ← markSent", "sneak.mjs ← recordPublishFailure"],
    "扫描器要把两个 token 都抓住 —— 期望写死，列表缩水就红");
});

// ─── 待认领话题快过期提醒（FR-8 补充，2026-08-28 Frank 要求）────────────────────────────
const H_MS = 3600000;
function claimReminderFixture({ base = NOW, name = "提醒演示" } = {}) {
  const local = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-cc-remind-"));
  const root = path.join(local, "project");
  fs.mkdirSync(root, { recursive: true });
  const registryFile = path.join(local, "registry.json");
  const templateFile = path.join(local, "chain-config.json");
  fs.writeFileSync(templateFile, JSON.stringify(TPL));
  const entry = newRegistryEntry({
    root, name, purpose: null, token: "aaa111", rootMessageId: "om_old", now: base,
  });
  assert.equal(entry.pending_expires_at, null, "首次绑定不设截止");
  fs.writeFileSync(registryFile, JSON.stringify({ schema_version: "1.0", projects: [entry] }, null, 2));
  assert.equal(promoteBinding({
    root, id: entry.id, source: "registry", generationId: entry.channel_generation_id,
    sessionId: "session_old", registryFile, now: base + 1,
  }).ok, true);
  assert.equal(prepareClaudeTopicRotation({ root, operationId: "op_remind", registryFile, now: base + 2 }).ok, true);
  const registered = registerClaudeTopicRotation({
    root, operationId: "op_remind", rootMessageId: "om_new", pendingToken: "bbb222", registryFile, now: base + 3,
  });
  assert.equal(registered.ok, true);
  assert.equal(registered.generation.claim_expires_at, null, "新代际不设截止");
  assert.equal(registered.generation.created_at, new Date(base + 3).toISOString());
  const createdAt = base + 3;
  const dueAt = createdAt + TG_REMINDER_AFTER_MS;       // 等满 72 小时：第一次该提醒的时刻
  const deadline = dueAt + 11 * H_MS;                    // 旧测试写法 `deadline - 11 * H_MS` 恰好等于 dueAt
  const readState = () => JSON.parse(fs.readFileSync(registryFile, "utf-8")).projects[0].topic_generation_state;
  const pendingOf = (state) => state.generations.find((g) => g.root_message_id === "om_new");
  return { root, local, entry, registryFile, templateFile, registered, createdAt, dueAt, deadline, readState, pendingOf, name };
}

test("待认领不过期：两条链都没有窗口常量；提醒节奏 72 小时首提醒、每 7 天一次；自动轮转阈值 50", () => {
  assert.equal(PENDING_WINDOW_MS, null, "首次绑定不再有窗口长度");
  assert.equal(TG_REMINDER_AFTER_MS, 72 * H_MS);
  assert.equal(TG_REMINDER_REPEAT_MS, 7 * 24 * H_MS);
  assert.equal(TOPIC_GENERATION_AUTO_ROTATE_MESSAGES, 50);
});

test("无人认领提醒的判据只有一份：等满 72 小时才提醒、提醒过再等 7 天、放弃过也再等 7 天；周期内最多 3 次、间隔 25 分钟；暂停 / 过期 / 没 created_at 不提醒", () => {
  const { readState, registered, pendingOf, createdAt, dueAt } = claimReminderFixture();
  const state = readState();
  const gid = registered.generation.channel_generation_id;
  const REPEAT = TG_REMINDER_REPEAT_MS;
  const notYet = tgClaimReminderDue(state, { now: dueAt - 1 });
  assert.deepEqual([notYet.due, notYet.reason, notYet.remainingMs, notYet.waitedMs], [false, "not_yet", 1, TG_REMINDER_AFTER_MS - 1]);
  const due = tgClaimReminderDue(state, { now: dueAt });
  assert.deepEqual([due.due, due.reason, due.attempts, due.waitedMs], [true, null, 0, TG_REMINDER_AFTER_MS], "等满 72 小时就该提醒");
  assert.equal(due.generation.channel_generation_id, gid);
  assert.equal(tgClaimReminderDue(state, { now: dueAt + 30 * 24 * H_MS }).due, true, "不过期：一个月后没提醒过照样该提醒");
  assert.equal(tgClaimReminderDue(state, { now: dueAt, afterMs: 1 }).due, true, "after 可注入");

  // 显式截止（旧登记）仍按过期处理
  const withDeadline = structuredClone(state);
  pendingOf(withDeadline).claim_expires_at = new Date(dueAt + 1).toISOString();
  assert.equal(tgClaimReminderDue(withDeadline, { now: dueAt }).due, true);
  assert.equal(tgClaimReminderDue(withDeadline, { now: dueAt + 1 }).reason, "expired");
  const noCreated = structuredClone(state);
  pendingOf(noCreated).created_at = undefined;
  assert.equal(tgClaimReminderDue(noCreated, { now: dueAt }).reason, "no_created_at", "说不清等了多久就不提醒");
  const paused = structuredClone(state);
  paused.binding_status = "paused";
  assert.equal(tgClaimReminderDue(paused, { now: dueAt }).reason, "binding_not_active");
  const none = structuredClone(state);
  none.generations = none.generations.filter((g) => g.status !== "pending");
  assert.equal(tgClaimReminderDue(none, { now: dueAt }).reason, "no_pending");

  // 提醒成功 → 本周期结束：7 天内 reminded_recently，7 天后再次 due，计数从 0 起
  const marked = tgMarkPendingClaimReminder(state, { generationId: gid, now: dueAt });
  assert.deepEqual([marked.ok, marked.changed], [true, true]);
  assert.equal(pendingOf(marked.state).claim_reminder_at, new Date(dueAt).toISOString());
  assert.equal(tgValidateState(marked.state).ok, true);
  assert.equal(tgClaimReminderDue(marked.state, { now: dueAt + REPEAT - 1 }).reason, "reminded_recently");
  const again = tgMarkPendingClaimReminder(marked.state, { generationId: gid, now: dueAt + REPEAT - 1 });
  assert.deepEqual([again.ok, again.changed], [true, false], "同一周期只记一次");
  const cycle2 = tgClaimReminderDue(marked.state, { now: dueAt + REPEAT });
  assert.deepEqual([cycle2.due, cycle2.attempts, cycle2.cycleStart], [true, 0, dueAt + REPEAT], "7 天后再提醒一次");
  assert.equal(tgMarkPendingClaimReminder(state, { generationId: "gen_other", now: dueAt }).reason, "pending_generation_mismatch");
  assert.equal(pendingOf(state).claim_reminder_at, undefined, "mark 是纯函数，不改入参");
  assert.equal(pendingOf(readState()).claim_reminder_at, undefined, "也不碰文件");

  // 锁内预留：拿到一次尝试后，同一周期再算就是 retry_too_soon；间隔够了再拿；拿满就 attempts_exhausted
  const r1 = tgReserveClaimReminderAttempt(state, { generationId: gid, now: dueAt });
  assert.deepEqual([r1.ok, r1.changed, r1.attempt, r1.waitedMs], [true, true, 1, TG_REMINDER_AFTER_MS]);
  assert.equal(pendingOf(r1.state).claim_reminder_attempted_at, new Date(dueAt).toISOString());
  assert.equal(tgValidateState(r1.state).ok, true);
  assert.equal(pendingOf(state).claim_reminder_attempts, undefined, "预留是纯函数");
  assert.equal(tgClaimReminderDue(r1.state, { now: dueAt + TG_REMINDER_RETRY_MS - 1 }).reason, "retry_too_soon");
  assert.equal(tgReserveClaimReminderAttempt(r1.state, { generationId: gid, now: dueAt + TG_REMINDER_RETRY_MS - 1 }).reason, "retry_too_soon");
  const r2 = tgReserveClaimReminderAttempt(r1.state, { generationId: gid, now: dueAt + TG_REMINDER_RETRY_MS });
  assert.deepEqual([r2.ok, r2.attempt], [true, 2]);
  let cur = r2.state;
  for (let i = 3; i <= TG_REMINDER_MAX_ATTEMPTS; i += 1) {
    const r = tgReserveClaimReminderAttempt(cur, { generationId: gid, now: dueAt + i * TG_REMINDER_RETRY_MS });
    assert.deepEqual([r.ok, r.attempt], [true, i]);
    cur = r.state;
  }
  const exhausted = tgClaimReminderDue(cur, { now: dueAt + 4 * TG_REMINDER_RETRY_MS });
  assert.deepEqual([exhausted.due, exhausted.reason, exhausted.attempts], [false, "attempts_exhausted", TG_REMINDER_MAX_ATTEMPTS]);
  assert.equal(tgReserveClaimReminderAttempt(cur, { generationId: gid, now: dueAt + 4 * TG_REMINDER_RETRY_MS }).reason, "attempts_exhausted");
  assert.equal(tgReserveClaimReminderAttempt(state, { generationId: "gen_other", now: dueAt }).reason, "pending_generation_mismatch");
  assert.equal(tgReserveClaimReminderAttempt(state, { generationId: gid, now: dueAt - 1 }).reason, "not_yet", "预留在锁内重算判据");
  // 放弃：本周期不再试，7 天后重来、计数清零
  const abandonedAt = dueAt + 4 * TG_REMINDER_RETRY_MS;
  const gaveUp = tgMarkPendingClaimReminderAbandoned(cur, { generationId: gid, now: abandonedAt });
  assert.deepEqual([gaveUp.ok, gaveUp.changed], [true, true]);
  assert.equal(pendingOf(gaveUp.state).claim_reminder_abandoned_at, new Date(abandonedAt).toISOString());
  assert.equal(tgValidateState(gaveUp.state).ok, true);
  assert.equal(tgClaimReminderDue(gaveUp.state, { now: abandonedAt + REPEAT - 1 }).reason, "abandoned_recently");
  const afterAbandon = tgClaimReminderDue(gaveUp.state, { now: abandonedAt + REPEAT });
  assert.deepEqual([afterAbandon.due, afterAbandon.attempts], [true, 0], "上个周期的 3 次不压住这个周期");
  // 提醒成功后计数与放弃标记清零
  const sent = tgMarkPendingClaimReminder(gaveUp.state, { generationId: gid, now: abandonedAt + REPEAT });
  const g = pendingOf(sent.state);
  assert.deepEqual([g.claim_reminder_attempts, g.claim_reminder_attempted_at, g.claim_reminder_abandoned_at], [null, null, null]);
  assert.equal(tgValidateState(sent.state).ok, true);

  // 形状：规范时间、封闭的尝试形状
  const bad = structuredClone(marked.state);
  pendingOf(bad).claim_reminder_at = "yesterday";
  assert.equal(tgValidateState(bad).ok, false, "非规范时间要被校验拦下");
  const sloppy = structuredClone(marked.state);
  pendingOf(sloppy).claim_reminder_at = "2026-08-28T00:00:00Z";
  assert.deepEqual(tgValidateState(sloppy).problems, ["generations.claim_reminder_at"]);
  const sloppyAbandon = structuredClone(state);
  pendingOf(sloppyAbandon).claim_reminder_abandoned_at = "2026-08-28T00:00:00Z";
  assert.deepEqual(tgValidateState(sloppyAbandon).problems, ["generations.claim_reminder_abandoned_at"]);
  const sloppyAttempt = structuredClone(state);
  pendingOf(sloppyAttempt).claim_reminder_attempted_at = "2026-08-28T00:00:00Z";
  pendingOf(sloppyAttempt).claim_reminder_attempts = -1;
  assert.deepEqual(tgValidateState(sloppyAttempt).problems.sort(),
    ["generations.claim_reminder_attempted_at", "generations.claim_reminder_attempts"]);
  const countOnly = structuredClone(state);
  pendingOf(countOnly).claim_reminder_attempts = 2;
  assert.deepEqual(tgValidateState(countOnly).problems, ["generations.claim_reminder_attempted_at"]);
  const timeOnly = structuredClone(state);
  pendingOf(timeOnly).claim_reminder_attempted_at = new Date(dueAt).toISOString();
  assert.deepEqual(tgValidateState(timeOnly).problems, ["generations.claim_reminder_attempts"]);
  const zero = structuredClone(timeOnly);
  pendingOf(zero).claim_reminder_attempts = 0;
  assert.deepEqual(tgValidateState(zero).problems, ["generations.claim_reminder_attempts"]);
  const bothNull = structuredClone(state);
  pendingOf(bothNull).claim_reminder_attempts = null;
  pendingOf(bothNull).claim_reminder_attempted_at = null;
  assert.equal(tgValidateState(bothNull).ok, true);
  assert.equal(tgReserveClaimReminderAttempt(countOnly, { generationId: gid, now: dueAt }).reason,
    "topic_generation_state_invalid", "预留在锁内校验形状，不让畸形状态绕过间隔");
});

test("Claude 扫描：进窗口的待认领话题只提醒一次、发在那个话题下、先发后记；发失败不记、下轮再发；dry-run 只说不发", () => {
  const fx = claimReminderFixture();
  const calls = [];
  const publish = (args) => { calls.push(args); };
  const sweep = (f, over) => remindClaudePendingClaims({
    registryFile: f.registryFile, templateFile: f.templateFile, publish, ...over,
  });
  const early = sweep(fx, { now: fx.dueAt - 1 });
  assert.equal(early.ok, true);
  assert.deepEqual([early.reminded, early.problems, calls.length], [[], [], 0]);
  assert.deepEqual(early.skipped, [{ name: fx.name, reason: "not_yet" }]);
  assert.equal(describeReminderSweep(early, { chain: "Claude" }), null, "没事就别出声");

  const now = fx.deadline - 11 * H_MS;
  const first = sweep(fx, { now });
  assert.deepEqual(first.problems, []);
  assert.deepEqual(first.reminded, [{ name: fx.name, generation: 2, attempt: 1, recorded: true }]);
  assert.equal(calls.length, 1);
  assert.equal(calls[0].rootMessageId, "om_new", "提醒要发在待认领的那个话题下，不是旧话题");
  assert.equal(calls[0].profile, TPL.lark_cli_profile);
  assert.equal(calls[0].expectedAppId, TPL.outbound_app_id);
  assert.equal(calls[0].larkBin, TPL.lark_cli_bin);
  assert.match(calls[0].text, /第 2 代/u);
  assert.match(calls[0].text, /已等待约 3 天，无人认领。它不会过期/u);
  assert.match(calls[0].text, /@/u, "要说清怎么认领");
  assert.match(calls[0].text, /不想要这个新话题：\/feishu-rotate cancel/u, "要说清怎么取消");
  assert.match(calls[0].text, /每 7 天提醒一次；发送失败时最多重试 3 次/u);
  assert.ok(!calls[0].text.includes("om_new") && !calls[0].text.includes("om_old"), "提醒正文不带 locator");
  assert.equal(fx.pendingOf(fx.readState()).claim_reminder_at, new Date(now).toISOString(), "发完要记进代际状态");
  assert.equal(fx.pendingOf(fx.readState()).claim_reminder_attempts, null, "提醒成功 = 本周期结束，尝试计数清零");
  assert.equal(fx.pendingOf(fx.readState()).claim_reminder_attempted_at, null);
  assert.match(describeReminderSweep(first, { chain: "Claude" }), /^Claude 待认领提醒：已提醒 提醒演示 第 2 代$/u);

  const second = sweep(fx, { now: now + 30 * 60000 });
  assert.deepEqual([second.reminded, second.problems, calls.length], [[], [], 1], "只提醒一次");
  assert.deepEqual(second.skipped, [{ name: fx.name, reason: "reminded_recently" }]);
  const late = sweep(fx, { now: now + 6 * 24 * H_MS });
  assert.deepEqual([late.reminded, late.problems, calls.length], [[], [], 1]);
  assert.deepEqual(late.skipped, [{ name: fx.name, reason: "reminded_recently" }], "7 天内不再提醒");
  const weekLater = sweep(fx, { now: now + TG_REMINDER_REPEAT_MS });
  assert.deepEqual([weekLater.reminded, calls.length], [[{ name: fx.name, generation: 2, attempt: 1, recorded: true }], 2], "7 天后再提醒一次");
  assert.match(calls[1].text, /已等待约 10 天/u);
  assert.equal(fx.pendingOf(fx.readState()).claim_reminder_at, new Date(now + TG_REMINDER_REPEAT_MS).toISOString());

  const fx2 = claimReminderFixture();
  const failed = sweep(fx2, { now, publish: () => { throw new Error("lark down"); } });
  assert.equal(failed.ok, true);
  assert.deepEqual(failed.reminded, []);
  assert.equal(failed.problems.length, 1);
  assert.equal(failed.problems[0].reason, "publish_failed");
  assert.match(failed.problems[0].error, /第 1\/3 次：lark down/u);
  assert.equal(fx2.pendingOf(fx2.readState()).claim_reminder_at, undefined, "预留 → 发 → 记：没发出去就不许记");
  assert.equal(fx2.pendingOf(fx2.readState()).claim_reminder_attempts, 1, "但这次尝试要留痕");
  assert.match(describeReminderSweep(failed, { chain: "Claude" }), /提醒有问题.*提醒演示（publish_failed：第 1\/3 次：lark down）/u);
  const tooSoon = sweep(fx2, { now: now + TG_REMINDER_RETRY_MS - 1 });
  assert.deepEqual([tooSoon.reminded, tooSoon.problems], [[], []]);
  assert.deepEqual(tooSoon.skipped, [{ name: fx2.name, reason: "retry_too_soon" }], "间隔没到不重试");
  const retry = sweep(fx2, { now: now + 30 * 60000 });
  assert.deepEqual(retry.reminded, [{ name: fx2.name, generation: 2, attempt: 2, recorded: true }], "上轮没发出去，这轮再发");
  assert.equal(calls.length, 3);

  // 连续失败到上限：放弃并报出来，之后不再发
  const fx4 = claimReminderFixture();
  const boom = () => { throw new Error("still down"); };
  for (let i = 1; i <= TG_REMINDER_MAX_ATTEMPTS; i += 1) {
    const r = sweep(fx4, { now: now + i * TG_REMINDER_RETRY_MS, publish: boom });
    const last = i === TG_REMINDER_MAX_ATTEMPTS;
    assert.equal(r.problems[0]?.reason, last ? "reminder_abandoned" : "publish_failed", "第 " + i + " 次");
    assert.match(r.problems[0].error, new RegExp("第 " + i + "\\/" + TG_REMINDER_MAX_ATTEMPTS + " 次"));
    if (last) {
      assert.match(r.problems[0].error, /本周期放弃，下个周期再试$/u, "放弃要记上（没记上会带括号说明）");
      assert.equal(fx4.pendingOf(fx4.readState()).claim_reminder_abandoned_at, new Date(now + i * TG_REMINDER_RETRY_MS).toISOString());
    }
  }
  const abandonedAt = now + TG_REMINDER_MAX_ATTEMPTS * TG_REMINDER_RETRY_MS;
  const gaveUp = sweep(fx4, { now: abandonedAt + TG_REMINDER_RETRY_MS });
  assert.deepEqual([gaveUp.reminded, gaveUp.problems, calls.length], [[], [], 3], "放弃后本周期不再发、也不再报");
  assert.deepEqual(gaveUp.skipped, [{ name: fx4.name, reason: "abandoned_recently" }]);
  assert.equal(describeReminderSweep(gaveUp, { chain: "Claude" }), null);
  const nextCycle = sweep(fx4, { now: abandonedAt + TG_REMINDER_REPEAT_MS });
  assert.deepEqual([nextCycle.reminded, calls.length], [[{ name: fx4.name, generation: 2, attempt: 1, recorded: true }], 4], "下个周期重来，计数从 1 起");

  // 并发：第二个扫描器在"预留之后、记之前"进来 —— 用发布回调里的嵌套扫描模拟。预留已持久化，它拿不到这次尝试。
  const fx5 = claimReminderFixture();
  let nested = null;
  const reentrant = (args) => {
    calls.push(args);
    nested = sweep(fx5, { now, publish: (a) => { calls.push(a); } });
  };
  const outer = sweep(fx5, { now, publish: reentrant });
  assert.deepEqual([outer.reminded.length, outer.problems], [1, []]);
  assert.deepEqual([nested.reminded, nested.problems], [[], []], "并发的第二个扫描器不许再发");
  assert.deepEqual(nested.skipped, [{ name: fx5.name, reason: "retry_too_soon" }]);
  assert.equal(calls.length, 5, "总共只多发了一条（外层那条）");
  assert.equal(fx5.pendingOf(fx5.readState()).claim_reminder_at, new Date(now).toISOString());

  // 暂停的绑定不提醒（跟出站同一条语义）
  const fx6 = claimReminderFixture();
  assert.equal(setClaudeTopicBindingStatus({ root: fx6.root, status: "paused", registryFile: fx6.registryFile, now }).ok, true);
  const pausedSweep = sweep(fx6, { now });
  assert.deepEqual([pausedSweep.reminded, pausedSweep.problems, calls.length], [[], [], 5]);
  assert.deepEqual(pausedSweep.skipped, [{ name: fx6.name, reason: "binding_not_active" }]);

  const fx3 = claimReminderFixture();
  const dry = sweep(fx3, { now, dryRun: true });
  assert.deepEqual(dry.reminded, [{ name: fx3.name, generation: 2, dryRun: true }]);
  assert.equal(calls.length, 5, "dry-run 不发");
  assert.equal(fx3.pendingOf(fx3.readState()).claim_reminder_at, undefined, "dry-run 不记");
  assert.match(describeReminderSweep(dry, { chain: "Claude" }), /\[dry-run\] 将提醒 提醒演示 第 2 代/u);
  // 旧登记带显式截止且已过：不提醒
  const reg3 = JSON.parse(fs.readFileSync(fx3.registryFile, "utf-8"));
  reg3.projects[0].topic_generation_state.generations.find((g) => g.root_message_id === "om_new").claim_expires_at = new Date(now - 1).toISOString();
  fs.writeFileSync(fx3.registryFile, JSON.stringify(reg3, null, 2));
  const expired = sweep(fx3, { now });
  assert.deepEqual([expired.reminded, calls.length], [[], 5], "显式截止已过就不提醒");
  assert.ok(["expired", "no_pending"].includes(expired.skipped[0]?.reason), JSON.stringify(expired.skipped));

  // 登记表不存在 = 空表（没接过桥），不算读不了；读不了是"有文件但坏了"。
  const corrupt = path.join(path.dirname(fx3.registryFile), "corrupt.json");
  fs.writeFileSync(corrupt, "{not json");
  const unreadable = remindClaudePendingClaims({ registryFile: corrupt, publish, now });
  assert.equal(unreadable.ok, false, JSON.stringify(unreadable));
  assert.equal(calls.length, 5);
  assert.match(describeReminderSweep(unreadable, { chain: "Claude" }), /登记表读不了/u);
});

test("单代际流程：预留阶段只有受控原因算跳过，登记表 / 状态错误必须进 problems；身份在确认要发之后才解析、抛错不外泄", () => {
  const fx = claimReminderFixture();
  const now = fx.deadline - 11 * H_MS;
  const state = fx.readState();
  const identity = { profile: "p", bin: "/bin/lark", configDir: "/d", expectedAppId: "cli_x" };
  const run = (over) => remindOnePendingClaim({
    name: "n", state, now, dryRun: false, identity: () => identity, publish: () => {},
    reserve: () => ({ ok: true, attempt: 1 }), mark: () => ({ ok: true }), ...over,
  });
  assert.deepEqual(run({ reserve: () => ({ ok: false, reason: "binding_busy" }) }),
    { outcome: "skipped", entry: { name: "n", reason: "binding_busy" } });
  assert.deepEqual(run({ reserve: () => ({ ok: false, reason: "retry_too_soon" }) }).outcome, "skipped");
  const invalid = run({ reserve: () => ({ ok: false, reason: "topic_generation_state_invalid", problems: ["x"] }) });
  assert.deepEqual(invalid, { outcome: "problem", entry: { name: "n", reason: "reserve_failed", error: "topic_generation_state_invalid" } });
  const unwritable = run({ reserve: () => ({ ok: false, reason: "binding_unwritable", error: "EACCES" }) });
  assert.deepEqual([unwritable.outcome, unwritable.entry.reason, unwritable.entry.error], ["problem", "reserve_failed", "binding_unwritable：EACCES"]);
  assert.deepEqual(run({ reserve: () => ({ ok: false, reason: "attempts_exhausted", attempts: 3 }) }).entry.reason, "reminder_abandoned");

  let reserveCalls = 0;
  const thrown = run({ identity: () => { throw new TypeError("path must be a string"); }, reserve: () => { reserveCalls += 1; return { ok: true, attempt: 1 }; } });
  assert.deepEqual([thrown.outcome, thrown.entry.reason, reserveCalls], ["problem", "identity_unresolvable", 0], "身份解析失败不许烧掉一次尝试");
  assert.match(thrown.entry.error, /path must be a string/u);
  const tagged = run({ identity: () => { throw Object.assign(new Error("no template"), { reason: "template_unavailable" }); } });
  assert.deepEqual([tagged.outcome, tagged.entry.reason], ["problem", "template_unavailable"]);
  assert.deepEqual(run({ identity: () => null }).entry.reason, "config_unavailable");
  let identityCalls = 0;
  const dry = run({ dryRun: true, identity: () => { identityCalls += 1; return identity; } });
  assert.deepEqual([dry.outcome, dry.entry.dryRun, identityCalls], ["reminded", true, 0], "dry-run 不解析身份");
  const early = remindOnePendingClaim({ name: "n", state, now: fx.dueAt - 1, dryRun: false,
    identity: () => { identityCalls += 1; return identity; }, publish: () => {}, reserve: () => ({ ok: true }), mark: () => ({ ok: true }) });
  assert.deepEqual([early.outcome, identityCalls], ["skipped", 0], "不到窗口不解析身份");
});

test("Claude 扫描：一个项目的坏配置只算它自己的问题，后面的项目照常提醒", () => {
  // 评审探针：项目侧旧配置不经模板形状校验，resolveLarkIdentity 里的 path.join 会抛 TypeError。
  const bad = claimReminderFixture({ name: "坏配置" });
  const good = claimReminderFixture({ name: "好项目" });
  // 老装法：没有机器模板，项目文件里的配置独自够用 —— 也就没有模板把链路字段压过去。
  const writeCfg = (fx, over) => {
    const cfgDir = path.join(fx.root, ".runtime-data", "inbound");
    fs.mkdirSync(cfgDir, { recursive: true });
    fs.writeFileSync(path.join(cfgDir, "chain-config.json"), JSON.stringify({
      ...TPL, project_dir: fx.root, task_display_name: fx.name, project_display_name: fx.name, ...over,
    }));
  };
  writeCfg(bad, { outbound_app_id: "cli_same", transport_app_id: "cli_same", agent_uid: "u", lark_cli_config_base: 42 });
  writeCfg(good, {});
  const missingTemplate = path.join(bad.local, "missing-template.json");
  const merged = path.join(bad.local, "merged-registry.json");
  const readProjects = (f) => JSON.parse(fs.readFileSync(f, "utf-8")).projects;
  fs.writeFileSync(merged, JSON.stringify({ schema_version: "1.0", projects: [...readProjects(bad.registryFile), ...readProjects(good.registryFile)] }, null, 2));
  const calls = [];
  const now = good.deadline - 11 * H_MS;
  const r = remindClaudePendingClaims({ registryFile: merged, templateFile: missingTemplate, now, publish: (a) => { calls.push(a); } });
  assert.equal(r.ok, true);
  assert.deepEqual(r.problems.map((p) => [p.name, p.reason]), [["坏配置", "identity_unresolvable"]], JSON.stringify(r.problems));
  assert.deepEqual(r.reminded, [{ name: "好项目", generation: 2, attempt: 1, recorded: true }]);
  assert.equal(calls.length, 1);
  const badState = readProjects(merged).find((p) => p.name === "坏配置").topic_generation_state;
  assert.equal(badState.generations.find((g) => g.root_message_id === "om_new").claim_reminder_attempts, undefined, "身份解析失败不烧尝试");
  const dry = remindClaudePendingClaims({ registryFile: merged, templateFile: missingTemplate, now, publish: () => { throw new Error("no"); }, dryRun: true });
  assert.deepEqual([dry.problems, dry.reminded], [[], [{ name: "坏配置", generation: 2, dryRun: true }]],
    "dry-run 不碰身份：坏配置那个也只说会提醒；好项目刚已提醒过，不再算");
});

test("锁目录不可写：预留报 lock_io_error，扫描记成 reserve_failed，不是静默跳过", () => {
  // 评审探针：适配层曾把任何取锁失败都改写成 binding_busy，而 busy 在跳过白名单里 —— 兜底成功退出、没有问题记录。
  const fx = claimReminderFixture();
  const now = fx.deadline - 11 * H_MS;
  const calls = [];
  fs.chmodSync(fx.local, 0o500);
  try {
    const reserved = reserveClaudeClaimReminder({ root: fx.root, generationId: fx.registered.generation.channel_generation_id,
      registryFile: fx.registryFile, templateFile: fx.templateFile, now });
    assert.deepEqual([reserved.ok, reserved.reason], [false, "lock_io_error"], JSON.stringify(reserved));
    assert.match(String(reserved.error), /EACCES|EPERM/u);
    const r = remindClaudePendingClaims({ registryFile: fx.registryFile, templateFile: fx.templateFile, now, publish: (a) => { calls.push(a); } });
    assert.deepEqual([r.ok, r.reminded, r.skipped, calls.length], [true, [], [], 0]);
    assert.deepEqual(r.problems.map((p) => [p.name, p.reason]), [[fx.name, "reserve_failed"]], JSON.stringify(r.problems));
    assert.match(r.problems[0].error, /lock_io_error：.*(EACCES|EPERM)/u);
  } finally {
    fs.chmodSync(fx.local, 0o700);
  }
});

test("两个真实 OS 进程同时扫描同一个待认领话题：只发一条（预留在锁内、锁无中间态）", () => {
  const fx = claimReminderFixture();
  const now = fx.deadline - 11 * H_MS;
  const log = path.join(fx.local, "publish.log");
  const worker = path.join(fx.local, "worker.mjs");
  const driver = path.join(fx.local, "driver.mjs");
  fs.writeFileSync(worker, [
    'import fs from "node:fs";',
    'const { remindClaudePendingClaims } = await import(' + JSON.stringify(pathToFileURL(path.resolve("scripts", "claim-reminder.mjs")).href) + ');',
    'const [registryFile, templateFile, now, log] = process.argv.slice(2);',
    'const r = remindClaudePendingClaims({ registryFile, templateFile, now: Number(now), publish: (a) => {',
    '  fs.appendFileSync(log, process.pid + " " + a.rootMessageId + "\\n");',
    '  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 400);',
    '} });',
    'process.stdout.write(JSON.stringify({ reminded: r.reminded.length, skipped: r.skipped.map((s) => s.reason), problems: r.problems }));',
  ].join("\n"));
  fs.writeFileSync(driver, [
    'import { spawn } from "node:child_process";',
    'const [worker, ...rest] = process.argv.slice(2);',
    'const run = () => new Promise((res) => {',
    '  const c = spawn(process.execPath, [worker, ...rest], { stdio: ["ignore", "pipe", "pipe"] });',
    '  let out = ""; let err = "";',
    '  c.stdout.on("data", (d) => { out += d; }); c.stderr.on("data", (d) => { err += d; });',
    '  c.on("close", (code) => res({ code, out, err }));',
    '});',
    'process.stdout.write(JSON.stringify(await Promise.all([run(), run()])));',
  ].join("\n"));
  const r = spawnSync(process.execPath, [driver, worker, fx.registryFile, fx.templateFile, String(now), log], { encoding: "utf-8" });
  assert.equal(r.status, 0, r.stderr);
  const results = JSON.parse(r.stdout);
  for (const w of results) assert.equal(w.code, 0, w.err);
  const parsed = results.map((w) => JSON.parse(w.out));
  assert.deepEqual(parsed.map((p) => p.problems), [[], []], JSON.stringify(parsed));
  assert.equal(parsed.reduce((n, p) => n + p.reminded, 0), 1, "两个进程加起来只提醒一次：" + JSON.stringify(parsed));
  const lines = fs.existsSync(log) ? fs.readFileSync(log, "utf-8").trim().split("\n") : [];
  assert.equal(lines.length, 1, "只发了一条：" + lines.join(" | "));
  const other = parsed.find((p) => p.reminded === 0);
  assert.ok(["retry_too_soon", "binding_busy"].includes(other.skipped[0]), JSON.stringify(other));
  assert.equal(fx.pendingOf(fx.readState()).claim_reminder_at, new Date(now).toISOString());
});

