  assert.ok(typeof uglyReceipt.diagnostic === "string" && !uglyReceipt.diagnostic.includes("\u001b") && !uglyReceipt.diagnostic.includes("oc_1234567890abcdef"), "机器级回执里的诊断片段已脱敏：" + uglyReceipt.diagnostic);
